/* World events, 1900–2026 — political and economic history.
 *
 * Fields
 *   d  date, ISO, variable precision: "1914" | "1914-07" | "1914-07-28"
 *   t  title (short — this is the chip label)
 *   c  category: pol | war | econ | shock
 *   i  importance: 1 = world-defining, 2 = major, 3 = notable
 *   r  region: Global | Europe | Americas | Asia | Africa | MidEast | Oceania
 *   s  one- or two-sentence summary: what happened and why it mattered
 *
 * Date precision is deliberate. Where only the year or month is well established,
 * the date stops there rather than inventing a day.
 */
const EVENTS = [
// ── 1900s ──────────────────────────────────────────────────────────────────────
{d:"1900-06",t:"Boxer Rebellion",c:"war",i:2,r:"Asia",s:"An anti-foreign uprising besieged the legations in Peking; an eight-nation expeditionary force crushed it and imposed a crippling indemnity on the Qing, accelerating the dynasty's collapse."},
{d:"1900-03-14",t:"US Gold Standard Act",c:"econ",i:2,r:"Americas",s:"Fixed the dollar to gold alone, ending three decades of bimetallist agitation and locking the US into the classical gold-standard system that would govern world finance until 1914."},
{d:"1901-01-01",t:"Australia federates",c:"pol",i:2,r:"Oceania",s:"Six British colonies joined as the Commonwealth of Australia, creating a self-governing dominion and a template for gradual, negotiated independence within the empire."},
{d:"1901-01-10",t:"Spindletop oil strike",c:"econ",i:2,r:"Americas",s:"A Texas gusher flowing at unprecedented volume turned oil from a lamp fuel into an industrial commodity and launched the companies that became Gulf and Texaco."},
{d:"1901-01-22",t:"Death of Queen Victoria",c:"pol",i:3,r:"Europe",s:"Closed a 63-year reign that had defined the British imperial century and opened an Edwardian era of rising German and American power."},
{d:"1901-09-06",t:"McKinley assassinated",c:"pol",i:2,r:"Americas",s:"An anarchist's bullet made Theodore Roosevelt president at 42, bringing trust-busting, conservation and an assertive US role in the Caribbean and Pacific."},
{d:"1902-01-30",t:"Anglo-Japanese Alliance",c:"pol",i:2,r:"Asia",s:"Britain's first modern alliance with a non-European power ended its 'splendid isolation' and gave Japan the diplomatic cover to confront Russia."},
{d:"1902-05-31",t:"Boer War ends",c:"war",i:2,r:"Africa",s:"The Treaty of Vereeniging brought the Boer republics into the British Empire after a guerrilla war fought with blockhouses, farm burnings and concentration camps that scarred British prestige."},
{d:"1903-11-03",t:"Panama secedes from Colombia",c:"pol",i:2,r:"Americas",s:"Backed by US warships, Panama declared independence and within weeks signed away canal-zone sovereignty — the sharpest example of American gunboat diplomacy."},
{d:"1904-02-08",t:"Russo-Japanese War begins",c:"war",i:1,r:"Asia",s:"Japan's surprise attack on Port Arthur opened the first modern war in which an Asian power defeated a European empire, shattering assumptions of white military supremacy."},
{d:"1904-04-08",t:"Entente Cordiale",c:"pol",i:2,r:"Europe",s:"Britain and France settled colonial quarrels and began the alignment that would put them on the same side in 1914."},
{d:"1905-01-22",t:"Bloody Sunday, St Petersburg",c:"pol",i:2,r:"Europe",s:"Troops fired on a peaceful petition march to the Winter Palace, triggering the 1905 Revolution and destroying the myth of the benevolent Tsar."},
{d:"1905-06-07",t:"Norway leaves union with Sweden",c:"pol",i:3,r:"Europe",s:"A peaceful dissolution, confirmed by referendum, that became a rare model for negotiated national separation."},
{d:"1905-09-05",t:"Treaty of Portsmouth",c:"pol",i:2,r:"Asia",s:"Ended the Russo-Japanese War on terms favouring Japan; Russian defeat fed revolution at home and Japanese ambition abroad."},
{d:"1905-10-30",t:"October Manifesto",c:"pol",i:2,r:"Europe",s:"Nicholas II conceded a Duma and civil liberties to end the 1905 revolution — reforms he spent the next decade hollowing out."},
{d:"1906-04-07",t:"Algeciras Conference",c:"pol",i:3,r:"Africa",s:"Settled the First Moroccan Crisis in France's favour and left Germany diplomatically isolated, hardening the alliance blocs."},
{d:"1907-08-31",t:"Anglo-Russian Convention",c:"pol",i:2,r:"Europe",s:"Divided Persia into spheres of influence and completed the Triple Entente, leaving Europe split into two armed camps."},
{d:"1907-10",t:"Panic of 1907",c:"econ",i:2,r:"Americas",s:"A failed corner in copper stock triggered runs that only J.P. Morgan's private syndicate could stop — the humiliation that led directly to the Federal Reserve."},
{d:"1908-07-03",t:"Young Turk Revolution",c:"pol",i:2,r:"MidEast",s:"Officers forced the restoration of the Ottoman constitution, beginning the modernising, increasingly Turkish-nationalist rule that carried the empire into the World War."},
{d:"1908-10-06",t:"Austria annexes Bosnia",c:"pol",i:2,r:"Europe",s:"A unilateral annexation that enraged Serbia and Russia, rehearsing the Balkan crisis that would detonate in 1914."},
{d:"1908-11-15",t:"Belgium annexes Congo Free State",c:"pol",i:2,r:"Africa",s:"International outrage at mass atrocities under Leopold II's personal rule forced the Belgian state to take over — an early victory for a transnational human-rights campaign."},
{d:"1909-04-14",t:"Anglo-Persian Oil Company",c:"econ",i:2,r:"MidEast",s:"Founded after the first major Middle Eastern strike, it began the century-long entanglement of Western capital, oil and Gulf politics; it later became BP."},

// ── 1910s ──────────────────────────────────────────────────────────────────────
{d:"1910-05-31",t:"Union of South Africa",c:"pol",i:2,r:"Africa",s:"Merged British colonies and Boer republics into a self-governing dominion built on a whites-only franchise — the legal foundation on which apartheid was later constructed."},
{d:"1910-08-22",t:"Japan annexes Korea",c:"pol",i:2,r:"Asia",s:"Thirty-five years of colonial rule began, a grievance that still shapes Northeast Asian diplomacy."},
{d:"1910-11-20",t:"Mexican Revolution begins",c:"pol",i:2,r:"Americas",s:"A revolt against Porfirio Díaz became a decade of civil war that killed perhaps a million people and produced the 1917 constitution and land reform."},
{d:"1911-07-01",t:"Agadir Crisis",c:"pol",i:3,r:"Africa",s:"A German gunboat sent to Morocco pushed Britain and France closer together and convinced London that Germany sought European hegemony."},
{d:"1911-09-29",t:"Italo-Turkish War",c:"war",i:3,r:"Africa",s:"Italy seized Libya from the Ottomans, exposed Ottoman weakness and emboldened the Balkan states to attack a year later."},
{d:"1911-10-10",t:"Xinhai Revolution",c:"pol",i:1,r:"Asia",s:"The Wuchang uprising toppled the Qing dynasty and ended two millennia of imperial rule in China, opening four decades of warlordism, civil war and revolution."},
{d:"1912-01-01",t:"Republic of China proclaimed",c:"pol",i:2,r:"Asia",s:"Sun Yat-sen took office as provisional president; the Qing emperor abdicated in February, but real power passed to generals rather than parliament."},
{d:"1912-10-08",t:"First Balkan War",c:"war",i:2,r:"Europe",s:"A Balkan league drove the Ottomans almost entirely out of Europe, leaving a volatile scramble over the spoils."},
{d:"1913-06-29",t:"Second Balkan War",c:"war",i:3,r:"Europe",s:"The victors fell out over Macedonia; Bulgaria's defeat left revanchist grievances that determined alignments in both world wars."},
{d:"1913-12-23",t:"US Federal Reserve created",c:"econ",i:1,r:"Americas",s:"America finally built a central bank after the 1907 panic, creating the institution that would shape global money for the next century."},
{d:"1914-06-28",t:"Franz Ferdinand assassinated",c:"pol",i:1,r:"Europe",s:"Gavrilo Princip's shots in Sarajevo set off five weeks of ultimatums and mobilisations that ended in general European war."},
{d:"1914-07-28",t:"World War I begins",c:"war",i:1,r:"Global",s:"Austria-Hungary's declaration of war on Serbia pulled the alliance system into a four-year industrial war that killed some 17 million people and destroyed four empires."},
{d:"1914-08-15",t:"Panama Canal opens",c:"econ",i:2,r:"Americas",s:"Cut the sea route between the Atlantic and Pacific by thousands of miles and confirmed US strategic dominance of the Western Hemisphere."},
{d:"1915-04-24",t:"Armenian Genocide begins",c:"shock",i:1,r:"MidEast",s:"Ottoman authorities arrested Armenian intellectuals in Constantinople and began deportations and massacres that killed around a million people — the crime that gave rise to the word genocide."},
{d:"1915-04-25",t:"Gallipoli landings",c:"war",i:2,r:"MidEast",s:"An Allied attempt to knock the Ottomans out of the war failed at enormous cost, forging national identities in Australia, New Zealand and Turkey alike."},
{d:"1915-05-07",t:"Lusitania sunk",c:"war",i:3,r:"Europe",s:"A U-boat sank a liner carrying 128 Americans, hardening US opinion against Germany and constraining submarine warfare for two years."},
{d:"1916-02-21",t:"Battle of Verdun",c:"war",i:2,r:"Europe",s:"Ten months of attrition around a fortress city cost some 700,000 casualties and became the symbol of the war's futility."},
{d:"1916-04-24",t:"Easter Rising",c:"pol",i:2,r:"Europe",s:"A failed republican insurrection in Dublin whose executed leaders turned Irish opinion decisively toward independence."},
{d:"1916-05-16",t:"Sykes–Picot Agreement",c:"pol",i:1,r:"MidEast",s:"Britain and France secretly agreed to carve up Ottoman Arab lands, drawing the borders and the resentments that still define the modern Middle East."},
{d:"1916-07-01",t:"Battle of the Somme",c:"war",i:2,r:"Europe",s:"Britain suffered 57,000 casualties on the first day; the four-month offensive advanced a few miles and introduced the tank to warfare."},
{d:"1917-03-08",t:"February Revolution",c:"pol",i:1,r:"Europe",s:"Bread riots and mutiny in Petrograd forced Nicholas II to abdicate, ending three centuries of Romanov rule."},
{d:"1917-04-06",t:"US enters World War I",c:"war",i:1,r:"Global",s:"Unrestricted submarine warfare and the Zimmermann Telegram brought American manpower and credit into the war, tipping the balance and making the US a creditor superpower."},
{d:"1917-11-02",t:"Balfour Declaration",c:"pol",i:2,r:"MidEast",s:"Britain endorsed a Jewish national home in Palestine while promising not to prejudice existing communities — a contradiction at the root of the Israeli–Palestinian conflict."},
{d:"1917-11-07",t:"October Revolution",c:"pol",i:1,r:"Europe",s:"Bolsheviks seized power in Petrograd, creating the world's first communist state and the ideological division that organised the next seventy years."},
{d:"1918-03-03",t:"Treaty of Brest-Litovsk",c:"pol",i:2,r:"Europe",s:"Soviet Russia bought peace by surrendering Ukraine, the Baltics and a third of its population, freeing German divisions for a final western offensive."},
{d:"1918-03",t:"Spanish flu pandemic",c:"shock",i:1,r:"Global",s:"An H1N1 influenza killed an estimated 50 million people in under two years — more than the war itself — while wartime censorship suppressed early warnings."},
{d:"1918-11-09",t:"German Revolution",c:"pol",i:2,r:"Europe",s:"Naval mutiny spread into revolution; the Kaiser abdicated and a republic was proclaimed, born with the stigma of defeat that Weimar never escaped."},
{d:"1918-11-11",t:"Armistice ends WWI fighting",c:"war",i:1,r:"Global",s:"Guns fell silent at 11am; four empires had fallen, and the peace that followed set the terms of the next war."},
{d:"1919-01-21",t:"Irish War of Independence",c:"war",i:3,r:"Europe",s:"Guerrilla war against British rule that ended in the 1921 treaty, partition and a bitter civil war."},
{d:"1919-03-02",t:"Comintern founded",c:"pol",i:2,r:"Europe",s:"Moscow created an international body to direct communist parties worldwide, exporting revolution and giving every domestic left a foreign patron."},
{d:"1919-04-13",t:"Amritsar massacre",c:"pol",i:2,r:"Asia",s:"British troops fired on an unarmed crowd in an enclosed square, killing hundreds and converting a generation of Indian moderates to the independence cause."},
{d:"1919-05-04",t:"May Fourth Movement",c:"pol",i:2,r:"Asia",s:"Student protests at Versailles' transfer of Shandong to Japan launched a cultural and political awakening from which both the Nationalists and the Chinese Communist Party emerged."},
{d:"1919-06-28",t:"Treaty of Versailles",c:"pol",i:1,r:"Europe",s:"Imposed reparations, disarmament and war guilt on Germany; Keynes called it a Carthaginian peace, and its resentments fed the rise of Hitler."},

// ── 1920s ──────────────────────────────────────────────────────────────────────
{d:"1920-01-10",t:"League of Nations founded",c:"pol",i:1,r:"Global",s:"The first permanent body for collective security began work — fatally weakened when the US Senate refused to join."},
{d:"1920-01-17",t:"US Prohibition begins",c:"pol",i:3,r:"Americas",s:"A constitutional ban on alcohol created a vast criminal economy and was repealed as a failure thirteen years later."},
{d:"1920-04-25",t:"San Remo conference",c:"pol",i:2,r:"MidEast",s:"Allotted League mandates over Syria and Lebanon to France, Palestine and Mesopotamia to Britain, converting the Sykes–Picot bargain into international law."},
{d:"1920-08-18",t:"US women win the vote",c:"pol",i:2,r:"Americas",s:"The 19th Amendment enfranchised women nationwide after a seventy-year campaign, part of a post-war wave of suffrage across the democracies."},
{d:"1921-03",t:"Lenin's New Economic Policy",c:"econ",i:2,r:"Europe",s:"After famine and revolt, the Bolsheviks restored limited private trade to save the economy — a retreat Stalin would violently reverse."},
{d:"1922-10-28",t:"Mussolini's March on Rome",c:"pol",i:1,r:"Europe",s:"A theatrical coup handed power to the first fascist government, giving Europe's authoritarian right a model and a vocabulary."},
{d:"1922-12-30",t:"Soviet Union established",c:"pol",i:1,r:"Europe",s:"The USSR was formally constituted from Russia, Ukraine, Belarus and Transcaucasia, creating the state that would define the century's second half."},
{d:"1923-01-11",t:"Occupation of the Ruhr",c:"econ",i:2,r:"Europe",s:"France seized Germany's industrial heartland over missed reparations; passive resistance and money-printing destroyed the mark."},
{d:"1923-10-29",t:"Republic of Turkey declared",c:"pol",i:2,r:"MidEast",s:"Atatürk replaced the Ottoman Empire with a secular nation-state and launched a programme of forced modernisation."},
{d:"1923-11",t:"German hyperinflation peaks",c:"econ",i:1,r:"Europe",s:"Prices doubled every few days and the mark fell to trillions per dollar, wiping out middle-class savings and permanently shaping German fear of inflation."},
{d:"1924-01-21",t:"Death of Lenin",c:"pol",i:2,r:"Europe",s:"Opened the succession struggle that Stalin won by 1928, turning the revolution toward one-man rule."},
{d:"1924-09-01",t:"Dawes Plan",c:"econ",i:2,r:"Europe",s:"American loans restructured German reparations and stabilised the currency, buying five prosperous years that ended when Wall Street crashed."},
{d:"1925-12-01",t:"Locarno Treaties",c:"pol",i:2,r:"Europe",s:"Germany accepted its western borders voluntarily, producing a brief 'spirit of Locarno' optimism — and pointedly leaving the eastern borders open."},
{d:"1926-05-04",t:"British General Strike",c:"econ",i:3,r:"Europe",s:"Nine days of nationwide stoppage in support of the miners ended in defeat, marking the high-water mark of British industrial militancy."},
{d:"1927-04-12",t:"Shanghai massacre",c:"war",i:2,r:"Asia",s:"Chiang Kai-shek's purge of communist allies ended the first united front and began a civil war that ran, with interruptions, for 22 years."},
{d:"1928-08-27",t:"Kellogg–Briand Pact",c:"pol",i:3,r:"Global",s:"Sixty-odd states renounced war as an instrument of policy; unenforceable in the 1930s, it nonetheless underpinned the post-1945 law against aggression."},
{d:"1928-10-01",t:"First Soviet Five-Year Plan",c:"econ",i:2,r:"Europe",s:"Stalin launched forced industrialisation and collectivisation, building heavy industry at the cost of famine and mass coercion."},
{d:"1929-10-24",t:"Wall Street Crash",c:"econ",i:1,r:"Americas",s:"Panic selling on Black Thursday and Black Tuesday erased a decade of gains, ending the boom and beginning the slide into global depression."},

// ── 1930s ──────────────────────────────────────────────────────────────────────
{d:"1930-03-12",t:"Salt March",c:"pol",i:2,r:"Asia",s:"Gandhi's 240-mile walk to make salt from the sea turned civil disobedience into a mass movement and an international news story."},
{d:"1930-06-17",t:"Smoot–Hawley Tariff",c:"econ",i:2,r:"Americas",s:"Raised US duties on thousands of goods; retaliation helped world trade collapse by two-thirds, the textbook case against beggar-thy-neighbour policy."},
{d:"1931-09-18",t:"Japan invades Manchuria",c:"war",i:2,r:"Asia",s:"A staged railway bombing gave the Kwantung Army its pretext; the League's failure to respond exposed collective security as hollow."},
{d:"1931-09-21",t:"Britain leaves the gold standard",c:"econ",i:2,r:"Europe",s:"Sterling floated after a run on the pound; countries that devalued early recovered fastest, a lesson relearned in every later currency crisis."},
{d:"1932-11-08",t:"Roosevelt elected",c:"pol",i:2,r:"Americas",s:"A landslide won on the promise of a New Deal brought activist government to a country with a quarter of its workforce unemployed."},
{d:"1932",t:"Great Depression trough",c:"econ",i:1,r:"Global",s:"World industrial output fell by roughly a third and US unemployment reached 25%; the slump discredited liberal capitalism and fed extremism across Europe."},
{d:"1933-01-30",t:"Hitler becomes Chancellor",c:"pol",i:1,r:"Europe",s:"Appointed by conservatives who thought they could control him, he dismantled the republic within months through the Reichstag Fire Decree and Enabling Act."},
{d:"1933-03-04",t:"New Deal begins",c:"econ",i:1,r:"Americas",s:"A bank holiday, deposit insurance, public works and financial regulation redefined the state's responsibility for the economy across the democratic world."},
{d:"1933-10-14",t:"Germany quits the League",c:"pol",i:2,r:"Europe",s:"Withdrawal from the League and the disarmament conference began the open rearmament that the Versailles order could no longer prevent."},
{d:"1932-11",t:"Soviet famine (Holodomor)",c:"shock",i:1,r:"Europe",s:"Grain requisitioning during forced collectivisation caused famine that killed millions, some 3.5 million in Ukraine alone, where it is recognised as genocide."},
{d:"1934-10-16",t:"Long March begins",c:"war",i:2,r:"Asia",s:"A year-long retreat of 6,000 miles saved the Chinese Communists from annihilation and made Mao Zedong their leader."},
{d:"1935-10-03",t:"Italy invades Ethiopia",c:"war",i:2,r:"Africa",s:"Poison gas and aerial bombing against one of the last independent African states; the League's feeble sanctions killed its credibility for good."},
{d:"1935-09-15",t:"Nuremberg Laws",c:"pol",i:2,r:"Europe",s:"Stripped German Jews of citizenship and criminalised intermarriage, turning antisemitism into a legal system."},
{d:"1935-08-14",t:"US Social Security Act",c:"econ",i:2,r:"Americas",s:"Created old-age pensions and unemployment insurance, the foundation of the American welfare state."},
{d:"1936-03-07",t:"Rhineland remilitarised",c:"war",i:2,r:"Europe",s:"German troops re-entered the demilitarised zone against their own generals' advice; Anglo-French inaction convinced Hitler that risk paid."},
{d:"1936-07-17",t:"Spanish Civil War begins",c:"war",i:2,r:"Europe",s:"A military rising against the Republic became a three-year war and a rehearsal for the world war, with German and Italian aid deciding it for Franco."},
{d:"1936-08",t:"Great Purge",c:"pol",i:2,r:"Europe",s:"Show trials and mass executions killed perhaps 700,000 and gutted the Soviet officer corps on the eve of war."},
{d:"1936-12-11",t:"Abdication of Edward VIII",c:"pol",i:3,r:"Europe",s:"A constitutional crisis over marriage to a divorcée ended with the king's abdication, settling the monarchy's subordination to ministers."},
{d:"1937-07-07",t:"Second Sino-Japanese War",c:"war",i:1,r:"Asia",s:"The Marco Polo Bridge incident began full-scale war in China; by 1945 it had killed some 20 million people, and it is where the Second World War really started."},
{d:"1937-12-13",t:"Nanjing Massacre",c:"war",i:2,r:"Asia",s:"Japanese troops killed tens of thousands of civilians and prisoners over six weeks, an atrocity that still poisons Sino-Japanese relations."},
{d:"1938-03-12",t:"Anschluss with Austria",c:"pol",i:2,r:"Europe",s:"Germany annexed Austria to cheering crowds and no resistance, the first expansion of the Reich beyond its 1919 borders."},
{d:"1938-09-30",t:"Munich Agreement",c:"pol",i:1,r:"Europe",s:"Britain and France handed Czechoslovakia's borderlands to Hitler for 'peace for our time'; appeasement became the byword for conceding to aggressors."},
{d:"1938-11-09",t:"Kristallnacht",c:"pol",i:2,r:"Europe",s:"State-organised pogroms burned synagogues and looted Jewish businesses across Germany, the turn from legal persecution to open violence."},
{d:"1939-08-23",t:"Nazi–Soviet Pact",c:"pol",i:1,r:"Europe",s:"The two ideological enemies agreed not to fight and secretly divided Poland and the Baltics, removing the last obstacle to war."},
{d:"1939-09-01",t:"World War II begins in Europe",c:"war",i:1,r:"Global",s:"Germany invaded Poland; Britain and France declared war two days later, beginning six years that killed 70–85 million people."},

// ── 1940s ──────────────────────────────────────────────────────────────────────
{d:"1940-05-10",t:"Fall of France begins",c:"war",i:2,r:"Europe",s:"Blitzkrieg through the Ardennes defeated the strongest army in Europe in six weeks, leaving Britain alone and Hitler dominant from Norway to the Pyrenees."},
{d:"1940-05-26",t:"Dunkirk evacuation",c:"war",i:3,r:"Europe",s:"338,000 troops were lifted from the beaches, preserving the British army and turning a catastrophe into a myth of national resilience."},
{d:"1940-07-10",t:"Battle of Britain",c:"war",i:2,r:"Europe",s:"The RAF's defence of British airspace denied Germany the air superiority needed for invasion — the first German defeat of the war."},
{d:"1941-03-11",t:"Lend-Lease Act",c:"econ",i:2,r:"Americas",s:"Let the US supply Britain and later the USSR without payment, making America the arsenal of democracy while still formally neutral."},
{d:"1941-06-22",t:"Operation Barbarossa",c:"war",i:1,r:"Europe",s:"Germany invaded the Soviet Union along a 1,800-mile front, opening the war's decisive theatre and its most murderous campaign."},
{d:"1941-08-14",t:"Atlantic Charter",c:"pol",i:2,r:"Global",s:"Roosevelt and Churchill set out war aims — self-determination, free trade, collective security — that became the blueprint for the UN and the post-war order."},
{d:"1941-12-07",t:"Pearl Harbor",c:"war",i:1,r:"Global",s:"Japan's strike on the Pacific Fleet brought the United States into the war, converting separate conflicts into one global war America would win."},
{d:"1942-01-20",t:"Wannsee Conference",c:"shock",i:1,r:"Europe",s:"Officials coordinated the industrial murder of Europe's Jews; the Holocaust ultimately killed about six million people."},
{d:"1942-06-04",t:"Battle of Midway",c:"war",i:2,r:"Asia",s:"Four Japanese carriers sunk in a day ended Japan's offensive capacity and turned the Pacific war."},
{d:"1942-11",t:"Stalingrad and El Alamein",c:"war",i:2,r:"Europe",s:"The Soviet encirclement at Stalingrad and Montgomery's breakthrough in Egypt marked the war's turning point on two fronts within weeks."},
{d:"1943-02-02",t:"German surrender at Stalingrad",c:"war",i:1,r:"Europe",s:"An entire German army destroyed; from here the Eastern Front moved only westward, and Soviet power moved with it."},
{d:"1943",t:"Bengal famine",c:"shock",i:2,r:"Asia",s:"Wartime policy, hoarding and export priorities killed some three million people in British India, a formative grievance in the independence struggle."},
{d:"1944-06-06",t:"D-Day landings",c:"war",i:1,r:"Europe",s:"156,000 Allied troops landed in Normandy, opening the western front that liberated France and shaped where the Iron Curtain would fall."},
{d:"1944-07-22",t:"Bretton Woods Conference",c:"econ",i:1,r:"Global",s:"Created the IMF and World Bank and pegged currencies to a gold-convertible dollar, the framework for a quarter-century of stability and growth."},
{d:"1945-02-04",t:"Yalta Conference",c:"pol",i:2,r:"Europe",s:"Roosevelt, Churchill and Stalin agreed occupation zones and 'free elections' in Eastern Europe — promises the Red Army's presence made meaningless."},
{d:"1945-05-08",t:"Victory in Europe",c:"war",i:1,r:"Europe",s:"Germany surrendered unconditionally; a devastated continent was left divided between Soviet and Western armies."},
{d:"1945-06-26",t:"United Nations Charter signed",c:"pol",i:1,r:"Global",s:"Fifty nations signed in San Francisco, creating a Security Council with great-power vetoes designed to keep the victors inside the system."},
{d:"1945-08-06",t:"Atomic bombing of Hiroshima",c:"war",i:1,r:"Asia",s:"A single weapon destroyed a city and killed some 140,000 by year's end; Nagasaki followed on 9 August, and warfare and diplomacy were permanently altered."},
{d:"1945-08-15",t:"Japan surrenders",c:"war",i:1,r:"Asia",s:"Ended the Second World War and began the American occupation that rebuilt Japan as a demilitarised industrial democracy."},
{d:"1945-11-20",t:"Nuremberg Trials open",c:"pol",i:2,r:"Europe",s:"Established that individuals, including heads of state, could be tried for crimes against humanity — the foundation of modern international criminal law."},
{d:"1946-03-05",t:"'Iron Curtain' speech",c:"pol",i:2,r:"Europe",s:"Churchill's Fulton address named the division of Europe and gave the emerging Cold War its defining image."},
{d:"1947-03-12",t:"Truman Doctrine",c:"pol",i:1,r:"Global",s:"Committed the US to containing communism worldwide, beginning with aid to Greece and Turkey — the strategic doctrine of the next forty years."},
{d:"1947-06-05",t:"Marshall Plan announced",c:"econ",i:1,r:"Europe",s:"$13 billion of American aid rebuilt Western Europe, tied recipients to the dollar system and hardened the continent's division."},
{d:"1947-08-15",t:"Partition of India",c:"pol",i:1,r:"Asia",s:"Independence for India and Pakistan came with a hurried border, communal massacres killing perhaps a million, and 15 million refugees — the largest migration in history."},
{d:"1947-10-30",t:"GATT signed",c:"econ",i:2,r:"Global",s:"Twenty-three countries began the rounds of tariff cuts that drove the post-war trade boom and eventually became the WTO."},
{d:"1948-05-14",t:"State of Israel declared",c:"pol",i:1,r:"MidEast",s:"Declaration was followed immediately by war with Arab states and the Palestinian Nakba, displacing some 700,000 people; the conflict remains unresolved."},
{d:"1948-06-24",t:"Berlin Blockade",c:"pol",i:2,r:"Europe",s:"Stalin cut off West Berlin; an eleven-month Allied airlift kept the city fed and made Berlin the Cold War's front line."},
{d:"1948-05-26",t:"Apartheid begins in South Africa",c:"pol",i:2,r:"Africa",s:"The National Party's election victory brought systematic racial segregation into law for the next four decades."},
{d:"1948-12-10",t:"Universal Declaration of Human Rights",c:"pol",i:2,r:"Global",s:"The UN General Assembly adopted a common standard of rights that became the reference point for every later human-rights movement."},
{d:"1949-04-04",t:"NATO founded",c:"pol",i:1,r:"Global",s:"Twelve nations bound themselves to treat an attack on one as an attack on all, ending American peacetime isolation for good."},
{d:"1949-08-29",t:"Soviet atomic bomb",c:"war",i:1,r:"Europe",s:"The US nuclear monopoly ended after four years, beginning the arms race and the logic of mutual deterrence."},
{d:"1949-10-01",t:"People's Republic of China",c:"pol",i:1,r:"Asia",s:"Mao proclaimed the PRC after Communist victory in the civil war; the Nationalists fled to Taiwan, and a quarter of humanity changed sides in the Cold War."},

// ── 1950s ──────────────────────────────────────────────────────────────────────
{d:"1950-06-25",t:"Korean War begins",c:"war",i:1,r:"Asia",s:"North Korea's invasion drew in UN forces and China; three years of fighting killed millions, froze the peninsula's division and militarised containment."},
{d:"1951-04-18",t:"European Coal and Steel Community",c:"econ",i:2,r:"Europe",s:"Six nations pooled the industries of war-making under a common authority — the first concrete step toward the European Union."},
{d:"1952-07-23",t:"Egyptian Revolution",c:"pol",i:2,r:"MidEast",s:"Free Officers deposed the monarchy and brought Nasser to power, launching Arab nationalism as a regional force."},
{d:"1953-03-05",t:"Death of Stalin",c:"pol",i:2,r:"Europe",s:"Ended a quarter-century of terror and opened a succession struggle that produced Khrushchev's thaw and the first Cold War negotiations."},
{d:"1953-07-27",t:"Korean Armistice",c:"war",i:2,r:"Asia",s:"Fighting stopped near the 38th parallel with no peace treaty; the DMZ remains one of the world's most militarised borders."},
{d:"1953-08-19",t:"Iran coup (Operation Ajax)",c:"pol",i:2,r:"MidEast",s:"US and British intelligence helped overthrow Mossadegh after he nationalised oil, restoring the Shah and seeding the anti-American grievance that erupted in 1979."},
{d:"1954-05-07",t:"Dien Bien Phu",c:"war",i:2,r:"Asia",s:"Vietnamese forces defeated the French garrison, ending French Indochina and dividing Vietnam at the 17th parallel."},
{d:"1954-05-17",t:"Brown v. Board of Education",c:"pol",i:2,r:"Americas",s:"The US Supreme Court struck down school segregation, giving the civil-rights movement its legal foundation."},
{d:"1954-11-01",t:"Algerian War begins",c:"war",i:2,r:"Africa",s:"Eight years of insurgency and torture that killed hundreds of thousands, brought down the French Fourth Republic and returned de Gaulle to power."},
{d:"1955-04-18",t:"Bandung Conference",c:"pol",i:2,r:"Asia",s:"Twenty-nine Asian and African states met as a third bloc, launching non-alignment and the political idea of the Third World."},
{d:"1955-05-14",t:"Warsaw Pact",c:"pol",i:2,r:"Europe",s:"Moscow's answer to West German rearmament and NATO formalised the military division of Europe."},
{d:"1956-02-25",t:"Khrushchev's Secret Speech",c:"pol",i:2,r:"Europe",s:"Denouncing Stalin's crimes to a closed party congress shook communist parties worldwide and encouraged reformers in Poland and Hungary."},
{d:"1956-10-23",t:"Hungarian Uprising",c:"pol",i:2,r:"Europe",s:"A revolution crushed by Soviet tanks within three weeks, killing some 2,500 and proving that the West would not intervene behind the Iron Curtain."},
{d:"1956-10-29",t:"Suez Crisis",c:"war",i:1,r:"MidEast",s:"Britain, France and Israel attacked Egypt over the nationalised canal, then withdrew under American financial pressure — the moment European empire visibly ended."},
{d:"1957-03-06",t:"Ghana independence",c:"pol",i:2,r:"Africa",s:"The first sub-Saharan colony to gain independence, setting off the decolonisation wave that produced dozens of new states."},
{d:"1957-03-25",t:"Treaty of Rome",c:"econ",i:1,r:"Europe",s:"Created the European Economic Community and a common market of six nations, the institutional core of today's EU."},
{d:"1957-10-04",t:"Sputnik launched",c:"pol",i:2,r:"Europe",s:"The first artificial satellite implied Soviet missiles could reach America, triggering the space race and a US overhaul of science education."},
{d:"1958-01",t:"Great Leap Forward",c:"shock",i:1,r:"Asia",s:"Mao's forced industrialisation and communal farming produced the deadliest famine in history, killing an estimated 30–45 million people by 1962."},
{d:"1958-09-28",t:"French Fifth Republic",c:"pol",i:2,r:"Europe",s:"De Gaulle's constitution created a strong presidency to end the instability of the Fourth Republic, and still governs France."},
{d:"1959-01-01",t:"Cuban Revolution",c:"pol",i:1,r:"Americas",s:"Castro's guerrillas took Havana; within two years Cuba had aligned with Moscow, putting the Cold War 90 miles from Florida."},

// ── 1960s ──────────────────────────────────────────────────────────────────────
{d:"1960",t:"Year of Africa",c:"pol",i:1,r:"Africa",s:"Seventeen African countries became independent in a single year, remaking the UN's membership and the politics of the Cold War's periphery."},
{d:"1960-03-21",t:"Sharpeville massacre",c:"pol",i:2,r:"Africa",s:"Police killed 69 anti-pass protesters; the ANC turned to armed struggle and South Africa began its long international isolation."},
{d:"1960-09-14",t:"OPEC founded",c:"econ",i:1,r:"MidEast",s:"Five oil exporters formed a cartel in Baghdad to wrest pricing power from the Western majors — leverage they would use decisively in 1973."},
{d:"1961-04-17",t:"Bay of Pigs invasion",c:"war",i:2,r:"Americas",s:"A CIA-backed exile landing failed within three days, humiliating Kennedy and pushing Castro further toward Moscow."},
{d:"1961-08-13",t:"Berlin Wall built",c:"pol",i:1,r:"Europe",s:"Overnight barriers sealed East Berlin to stop an exodus of skilled workers, and the Wall became the physical emblem of the divided world."},
{d:"1962-10-16",t:"Cuban Missile Crisis",c:"war",i:1,r:"Global",s:"Thirteen days of confrontation over Soviet missiles in Cuba brought the world closest to nuclear war and led directly to the hotline and test-ban treaty."},
{d:"1963-08-05",t:"Partial Test Ban Treaty",c:"pol",i:2,r:"Global",s:"Banned nuclear testing in the atmosphere, in space and underwater — the first real arms-control agreement of the nuclear age."},
{d:"1963-11-22",t:"Kennedy assassinated",c:"pol",i:2,r:"Americas",s:"Johnson's succession brought both the Great Society and the escalation in Vietnam."},
{d:"1964-07-02",t:"US Civil Rights Act",c:"pol",i:2,r:"Americas",s:"Outlawed segregation and employment discrimination, the central legislative achievement of the civil-rights movement."},
{d:"1964-08-07",t:"Gulf of Tonkin Resolution",c:"war",i:2,r:"Asia",s:"On disputed evidence, Congress gave Johnson open-ended war powers, opening the way to half a million US troops in Vietnam."},
{d:"1965-08-06",t:"US Voting Rights Act",c:"pol",i:2,r:"Americas",s:"Federal enforcement ended the devices that had disenfranchised Black voters in the South since Reconstruction."},
{d:"1965-09-30",t:"Indonesian mass killings",c:"shock",i:2,r:"Asia",s:"A failed coup was followed by army-led massacres of suspected communists that killed perhaps 500,000 and brought Suharto's 32-year rule."},
{d:"1966-05-16",t:"Cultural Revolution",c:"pol",i:1,r:"Asia",s:"Mao mobilised students against the party itself; a decade of purges and closed universities killed over a million and paralysed China."},
{d:"1967-06-05",t:"Six-Day War",c:"war",i:1,r:"MidEast",s:"Israel destroyed three Arab air forces and took the Sinai, Golan, West Bank and Gaza — the occupation that has defined the conflict ever since."},
{d:"1967-07-06",t:"Biafran War",c:"war",i:2,r:"Africa",s:"Nigeria's civil war and blockade of secessionist Biafra killed perhaps a million, mostly by starvation, and created modern televised famine relief."},
{d:"1968-01-30",t:"Tet Offensive",c:"war",i:2,r:"Asia",s:"A coordinated North Vietnamese assault was militarily repulsed but shattered American confidence that the war was being won."},
{d:"1968-05",t:"May 1968 in France",c:"pol",i:2,r:"Europe",s:"Student revolt and a ten-million-worker general strike nearly toppled de Gaulle and became shorthand for a worldwide year of upheaval."},
{d:"1968-08-20",t:"Prague Spring crushed",c:"pol",i:2,r:"Europe",s:"Warsaw Pact tanks ended Czechoslovak reform and produced the Brezhnev Doctrine — sovereignty limited for socialist states."},
{d:"1968-04-04",t:"Martin Luther King assassinated",c:"pol",i:2,r:"Americas",s:"Killed in Memphis; riots followed in over 100 cities and the civil-rights coalition fractured."},
{d:"1969-07-20",t:"Apollo 11 Moon landing",c:"pol",i:2,r:"Americas",s:"The US won the space race decisively, a Cold War victory watched live by 600 million people."},
{d:"1969-08",t:"Troubles begin in Northern Ireland",c:"war",i:2,r:"Europe",s:"British troops deployed to Belfast and Derry at the start of three decades of conflict that killed some 3,500 people."},

// ── 1970s ──────────────────────────────────────────────────────────────────────
{d:"1970-09-04",t:"Allende elected in Chile",c:"pol",i:2,r:"Americas",s:"The first Marxist elected president anywhere; his nationalisations and the US response made Chile a Cold War test case."},
{d:"1971-03-26",t:"Bangladesh Liberation War",c:"war",i:2,r:"Asia",s:"Pakistan's crackdown in the east killed hundreds of thousands and drove ten million refugees into India, whose intervention created Bangladesh in December."},
{d:"1971-08-15",t:"Nixon ends dollar–gold convertibility",c:"econ",i:1,r:"Global",s:"The 'Nixon shock' broke Bretton Woods and put the world on floating fiat currencies — the monetary system we still live in."},
{d:"1971-10-25",t:"PRC takes China's UN seat",c:"pol",i:2,r:"Asia",s:"The General Assembly transferred recognition from Taipei to Beijing, beginning the PRC's integration into the international system."},
{d:"1972-02-21",t:"Nixon visits China",c:"pol",i:1,r:"Asia",s:"A week in Beijing ended two decades of hostility, split the communist bloc and reset the Cold War's triangular geometry."},
{d:"1972-05-26",t:"SALT I and the ABM Treaty",c:"pol",i:2,r:"Global",s:"The superpowers capped missile launchers and limited defences, formalising mutual vulnerability as the basis of stability."},
{d:"1973-01-01",t:"Britain joins the EEC",c:"econ",i:2,r:"Europe",s:"After two French vetoes, Britain entered the common market — a membership it debated for 47 years and left in 2020."},
{d:"1973-09-11",t:"Chilean coup",c:"pol",i:2,r:"Americas",s:"Pinochet's junta overthrew Allende and ruled for 17 years, killing thousands while making Chile the first laboratory of neoliberal economics."},
{d:"1973-10-06",t:"Yom Kippur War",c:"war",i:2,r:"MidEast",s:"Egypt and Syria attacked on the Jewish holy day; the near-run war led to superpower nuclear alerts and, ultimately, to Camp David."},
{d:"1973-10-17",t:"First Oil Shock",c:"econ",i:1,r:"Global",s:"An Arab embargo quadrupled crude prices, ending the post-war boom and bringing stagflation, queues at pumps and a decade of Western economic anxiety."},
{d:"1974-08-09",t:"Nixon resigns",c:"pol",i:2,r:"Americas",s:"Watergate forced the first resignation of a US president, deepening a lasting decline in public trust in government."},
{d:"1974-04-25",t:"Carnation Revolution",c:"pol",i:2,r:"Europe",s:"A near-bloodless coup ended Europe's longest dictatorship and triggered Portugal's abrupt withdrawal from its African colonies."},
{d:"1975-04-17",t:"Khmer Rouge take Phnom Penh",c:"shock",i:1,r:"Asia",s:"Cambodia's cities were emptied and roughly a quarter of the population died in under four years of agrarian totalitarianism."},
{d:"1975-04-30",t:"Fall of Saigon",c:"war",i:1,r:"Asia",s:"North Vietnamese tanks entered the capital, ending thirty years of war and America's first clear military defeat."},
{d:"1975-08-01",t:"Helsinki Accords",c:"pol",i:2,r:"Europe",s:"The West accepted post-war borders in exchange for human-rights commitments that dissident movements across the Eastern bloc used against their governments."},
{d:"1975-11-20",t:"Death of Franco",c:"pol",i:2,r:"Europe",s:"Opened Spain's transition to constitutional monarchy and democracy, completed with the 1978 constitution."},
{d:"1976-09-09",t:"Death of Mao Zedong",c:"pol",i:2,r:"Asia",s:"The Gang of Four's arrest weeks later ended the Cultural Revolution and cleared the path for Deng Xiaoping's reforms."},
{d:"1978-12-18",t:"Deng launches Reform and Opening",c:"econ",i:1,r:"Asia",s:"The Third Plenum turned China toward markets, foreign investment and household farming, beginning the fastest large-scale escape from poverty in history."},
{d:"1978-09-17",t:"Camp David Accords",c:"pol",i:2,r:"MidEast",s:"Egypt became the first Arab state to recognise Israel in exchange for Sinai, breaking Arab unity and removing the largest army from the conflict."},
{d:"1979-02-11",t:"Iranian Revolution",c:"pol",i:1,r:"MidEast",s:"The Shah fell to a mass movement that produced an Islamic Republic, transforming Middle Eastern politics and Western energy security."},
{d:"1979-05-04",t:"Thatcher becomes PM",c:"pol",i:2,r:"Europe",s:"Privatisation, union laws and monetarism made Britain the European testbed for a market turn that spread across the democracies."},
{d:"1979-06",t:"Second Oil Shock",c:"econ",i:2,r:"Global",s:"Iranian disruption doubled crude prices again, producing double-digit inflation and the severe recession that followed."},
{d:"1979-11-04",t:"Iran hostage crisis",c:"pol",i:2,r:"MidEast",s:"Students seized the US embassy and held 52 diplomats for 444 days, destroying Carter's presidency and freezing US–Iran relations for decades."},
{d:"1979-12-24",t:"Soviet invasion of Afghanistan",c:"war",i:1,r:"Asia",s:"A nine-year war against US- and Saudi-backed mujahideen bled the Soviet Union militarily and financially and incubated transnational jihadism."},
{d:"1979-10-06",t:"Volcker shock",c:"econ",i:1,r:"Americas",s:"The Fed raised rates toward 20% to break inflation, causing deep recession, a debt crisis across the developing world, and the credibility of independent central banking."},

// ── 1980s ──────────────────────────────────────────────────────────────────────
{d:"1980-08-31",t:"Solidarity founded",c:"pol",i:2,r:"Europe",s:"The Gdańsk shipyard agreement created the Soviet bloc's first independent trade union, a ten-million-member movement that eventually negotiated communism's exit."},
{d:"1980-09-22",t:"Iran–Iraq War begins",c:"war",i:2,r:"MidEast",s:"Eight years of trench warfare and chemical weapons killed roughly a million people and left Iraq indebted and looking at Kuwait."},
{d:"1981-01-20",t:"Reagan inaugurated",c:"pol",i:2,r:"Americas",s:"Tax cuts, deregulation and a military build-up defined a conservative era and a more confrontational final phase of the Cold War."},
{d:"1982-04-02",t:"Falklands War",c:"war",i:3,r:"Americas",s:"Argentina's invasion and Britain's recapture of the islands secured Thatcher's re-election and collapsed the Argentine junta."},
{d:"1982-08",t:"Latin American debt crisis",c:"econ",i:2,r:"Americas",s:"Mexico's default on dollar debt began a 'lost decade' of austerity and IMF programmes across the region."},
{d:"1984-10-31",t:"Indira Gandhi assassinated",c:"pol",i:3,r:"Asia",s:"Killed by her bodyguards after the storming of the Golden Temple; anti-Sikh pogroms followed in Delhi."},
{d:"1984-12-03",t:"Bhopal gas disaster",c:"shock",i:2,r:"Asia",s:"A pesticide-plant leak killed thousands within days and became the defining case of corporate liability in the developing world."},
{d:"1985-03-11",t:"Gorbachev takes power",c:"pol",i:1,r:"Europe",s:"Glasnost and perestroika were meant to save the Soviet system; within six years they had dissolved it."},
{d:"1985-09-22",t:"Plaza Accord",c:"econ",i:2,r:"Global",s:"Five governments agreed to devalue the dollar against the yen and mark; the ensuing yen surge helped inflate Japan's asset bubble."},
{d:"1986-04-26",t:"Chernobyl disaster",c:"shock",i:1,r:"Europe",s:"A reactor explosion contaminated much of Europe and cost tens of billions; the cover-up discredited Soviet authority and turned Gorbachev toward real openness."},
{d:"1986-02-25",t:"People Power Revolution",c:"pol",i:2,r:"Asia",s:"Mass nonviolent protest drove Marcos from the Philippines, a template copied in democratic transitions worldwide."},
{d:"1987-10-19",t:"Black Monday",c:"econ",i:2,r:"Global",s:"Wall Street fell 22.6% in a day — still the largest one-day percentage drop — and central banks learned to flood markets with liquidity."},
{d:"1987-12-08",t:"INF Treaty",c:"pol",i:2,r:"Global",s:"Reagan and Gorbachev eliminated an entire class of nuclear missiles, the first treaty to cut rather than cap arsenals."},
{d:"1987-12-08",t:"First Intifada",c:"war",i:2,r:"MidEast",s:"A mass Palestinian uprising in the occupied territories changed the conflict's image worldwide and led eventually to Oslo."},
{d:"1989-06-04",t:"Tiananmen Square crackdown",c:"pol",i:1,r:"Asia",s:"The army cleared weeks of pro-democracy protest with hundreds to thousands killed, settling that China would pursue economic opening without political liberalisation."},
{d:"1989-11-09",t:"Fall of the Berlin Wall",c:"pol",i:1,r:"Europe",s:"A confused press conference sent crowds to the checkpoints; the Wall opened, and within a year Germany was reunified and the Eastern bloc had dissolved."},
{d:"1989-12-25",t:"Romanian Revolution",c:"pol",i:2,r:"Europe",s:"Ceaușescu's execution ended the only violent overthrow in the 1989 wave that swept Poland, Hungary, East Germany and Czechoslovakia."},

// ── 1990s ──────────────────────────────────────────────────────────────────────
{d:"1990-02-11",t:"Mandela released",c:"pol",i:1,r:"Africa",s:"After 27 years in prison he walked free to negotiate the end of apartheid, becoming the century's emblem of reconciliation."},
{d:"1990-08-02",t:"Iraq invades Kuwait",c:"war",i:2,r:"MidEast",s:"Saddam's annexation of an oil-rich neighbour produced the first post-Cold-War coalition war and a permanent US military presence in the Gulf."},
{d:"1990-10-03",t:"German reunification",c:"pol",i:1,r:"Europe",s:"East Germany acceded to the Federal Republic less than a year after the Wall fell, creating Europe's dominant economy."},
{d:"1990",t:"Japan's bubble bursts",c:"econ",i:1,r:"Asia",s:"The Nikkei began a fall of over 80% and land values collapsed, opening decades of deflation and near-zero growth that became the warning case for every later bubble."},
{d:"1991-01-17",t:"Gulf War",c:"war",i:2,r:"MidEast",s:"A US-led coalition expelled Iraq from Kuwait in six weeks of air power and a hundred-hour ground war, televised live and read as proof of American primacy."},
{d:"1991-06-25",t:"Yugoslav wars begin",c:"war",i:2,r:"Europe",s:"Slovenian and Croatian independence began a decade of wars, ethnic cleansing and siege that killed some 140,000 and returned genocide to Europe."},
{d:"1991-12-26",t:"Soviet Union dissolved",c:"pol",i:1,r:"Europe",s:"Fifteen republics became independent states and the Cold War ended without a shot; the world went briefly unipolar and Russia lost an empire."},
{d:"1991-07-24",t:"India's economic liberalisation",c:"econ",i:1,r:"Asia",s:"A balance-of-payments crisis forced the dismantling of the licence raj, unleashing growth that lifted hundreds of millions out of poverty."},
{d:"1992-02-07",t:"Maastricht Treaty",c:"pol",i:1,r:"Europe",s:"Created the European Union and committed members to a single currency, converting an economic community into a political project."},
{d:"1992-09-16",t:"Black Wednesday",c:"econ",i:2,r:"Europe",s:"Speculation forced sterling out of Europe's exchange-rate mechanism in a day, destroying the Conservatives' economic reputation and keeping Britain out of the euro."},
{d:"1994-01-01",t:"NAFTA takes effect",c:"econ",i:2,r:"Americas",s:"Created a North American free-trade zone, deepened cross-border supply chains and became the reference point in every later trade backlash."},
{d:"1994-04-07",t:"Rwandan genocide",c:"shock",i:1,r:"Africa",s:"About 800,000 Tutsi and moderate Hutu were killed in a hundred days while UN forces stood by — the defining failure of post-Cold-War humanitarian politics."},
{d:"1994-04-27",t:"South Africa's first free election",c:"pol",i:1,r:"Africa",s:"Mandela's election ended apartheid peacefully, a transition that had been widely predicted to end in civil war."},
{d:"1994-12-20",t:"Mexican peso crisis",c:"econ",i:2,r:"Americas",s:"A botched devaluation triggered capital flight and a US-led bailout, the first crisis of the era of fast-moving global capital."},
{d:"1995-01-01",t:"World Trade Organization",c:"econ",i:2,r:"Global",s:"GATT became a permanent body with binding dispute settlement, the institutional peak of trade globalisation."},
{d:"1995-07-11",t:"Srebrenica massacre",c:"shock",i:2,r:"Europe",s:"Bosnian Serb forces murdered more than 8,000 Muslim men and boys in a UN 'safe area', prompting NATO intervention and the Dayton Agreement."},
{d:"1997-07-01",t:"Hong Kong handover",c:"pol",i:2,r:"Asia",s:"Britain returned the territory to China under 'one country, two systems', a fifty-year promise that lasted barely twenty."},
{d:"1997-07-02",t:"Asian financial crisis",c:"econ",i:1,r:"Asia",s:"Thailand's devaluation cascaded across the region, collapsing currencies and governments and teaching Asian states to accumulate the dollar reserves that later financed America's deficits."},
{d:"1998-04-10",t:"Good Friday Agreement",c:"pol",i:2,r:"Europe",s:"Power-sharing and an open border ended thirty years of conflict in Northern Ireland, and became the model for negotiated settlements."},
{d:"1998-08-17",t:"Russian default",c:"econ",i:2,r:"Europe",s:"Moscow devalued and defaulted, sank the LTCM hedge fund and delivered the era's clearest lesson about leverage and correlated risk."},
{d:"1999-01-01",t:"Euro launched",c:"econ",i:1,r:"Europe",s:"Eleven countries adopted a single currency without a common treasury — a design flaw that the 2010 debt crisis exposed."},
{d:"1999-03-24",t:"NATO bombs Yugoslavia",c:"war",i:2,r:"Europe",s:"Eleven weeks of air strikes over Kosovo, launched without a Security Council mandate, set a precedent for humanitarian intervention that Russia still cites."},
{d:"1999-12-31",t:"Putin becomes acting president",c:"pol",i:1,r:"Europe",s:"Yeltsin's surprise resignation elevated a former KGB officer who would rule Russia, in one office or another, for the next quarter-century."},

// ── 2000s ──────────────────────────────────────────────────────────────────────
{d:"2000-03-10",t:"Dot-com bubble peaks",c:"econ",i:2,r:"Americas",s:"The Nasdaq topped out and then fell about 78% over two years, wiping out $5 trillion and ending the first internet mania."},
{d:"2001-09-11",t:"September 11 attacks",c:"war",i:1,r:"Global",s:"Al-Qaeda hijackers killed nearly 3,000 people in the US, launching two decades of war, surveillance and a reordering of American foreign policy."},
{d:"2001-10-07",t:"US invades Afghanistan",c:"war",i:2,r:"Asia",s:"The Taliban fell in weeks; the occupation lasted twenty years and ended with their return."},
{d:"2001-12-11",t:"China joins the WTO",c:"econ",i:1,r:"Asia",s:"Membership locked in access to world markets and made China the workshop of the world, remaking global manufacturing, wages and politics."},
{d:"2001-12",t:"Argentina defaults",c:"econ",i:2,r:"Americas",s:"The largest sovereign default to that point ended the peso's dollar peg amid riots and five presidents in two weeks."},
{d:"2002-01-01",t:"Euro notes and coins circulate",c:"econ",i:2,r:"Europe",s:"Twelve national currencies were physically replaced, the largest monetary changeover ever attempted."},
{d:"2003-03-20",t:"Invasion of Iraq",c:"war",i:1,r:"MidEast",s:"A US-led war launched over weapons that did not exist toppled Saddam, destabilised the region and shattered Western consensus on intervention."},
{d:"2003-02",t:"SARS outbreak",c:"shock",i:3,r:"Asia",s:"A coronavirus spread from southern China to 29 countries; contained within months, it rehearsed the containment playbook used again in 2020."},
{d:"2004-05-01",t:"EU's big-bang enlargement",c:"pol",i:2,r:"Europe",s:"Ten mostly post-communist states joined at once, reuniting the continent and setting off a decade of intra-European migration."},
{d:"2004-12-26",t:"Indian Ocean tsunami",c:"shock",i:2,r:"Asia",s:"A magnitude 9.1 quake killed some 228,000 people across fourteen countries and triggered the largest humanitarian response to that date."},
{d:"2004-11-22",t:"Orange Revolution",c:"pol",i:3,r:"Europe",s:"Mass protest overturned a rigged Ukrainian election, the first of the confrontations over Ukraine's alignment that led to war."},
{d:"2005-07-07",t:"London bombings",c:"war",i:3,r:"Europe",s:"Four suicide bombers killed 52 on the transport network, shifting European counter-terrorism toward home-grown radicalisation."},
{d:"2007-08-09",t:"Credit crunch begins",c:"econ",i:2,r:"Global",s:"BNP Paribas froze three funds over US subprime exposure and interbank lending seized up — the first crack in the global financial system."},
{d:"2008-09-15",t:"Lehman Brothers collapses",c:"econ",i:1,r:"Global",s:"The largest bankruptcy in US history froze world credit markets and turned a housing bust into the deepest global slump since the 1930s."},
{d:"2008-08-07",t:"Russia–Georgia war",c:"war",i:3,r:"Europe",s:"A five-day war left Russian troops in South Ossetia and Abkhazia, the first armed redrawing of a European border since the 1990s."},
{d:"2008-11-04",t:"Obama elected",c:"pol",i:2,r:"Americas",s:"The first Black US president took office amid the financial crisis, with large majorities that produced the Affordable Care Act."},
{d:"2009-04-02",t:"G20 London summit",c:"econ",i:2,r:"Global",s:"Coordinated stimulus and IMF funding stopped the free fall, and the G20 displaced the G7 as the crisis forum of record."},
{d:"2009-10",t:"Greek deficit revelation",c:"econ",i:2,r:"Europe",s:"A new government disclosed a deficit more than double the reported figure, opening the eurozone debt crisis."},

// ── 2010s ──────────────────────────────────────────────────────────────────────
{d:"2010-05-02",t:"First Greek bailout",c:"econ",i:2,r:"Europe",s:"€110 billion in loans came with austerity that shrank the economy by a quarter, testing the euro's design to destruction."},
{d:"2010-12-17",t:"Arab Spring begins",c:"pol",i:1,r:"MidEast",s:"A Tunisian street vendor's self-immolation set off uprisings across the Arab world, toppling four rulers and producing both democracy and civil war."},
{d:"2011-02-11",t:"Mubarak resigns",c:"pol",i:2,r:"MidEast",s:"Eighteen days of protest in Tahrir Square ended thirty years of rule; a 2013 coup reversed the opening."},
{d:"2011-03-11",t:"Fukushima disaster",c:"shock",i:2,r:"Asia",s:"A tsunami caused triple meltdown; Japan idled its reactors and Germany abandoned nuclear power, reshaping global energy policy."},
{d:"2011-03-15",t:"Syrian civil war begins",c:"war",i:1,r:"MidEast",s:"Protest met with gunfire became a war that killed over half a million, displaced 13 million and drew in Russia, Iran, Turkey and the US."},
{d:"2011-05-02",t:"Bin Laden killed",c:"war",i:2,r:"Asia",s:"A US raid in Abbottabad ended a decade-long hunt and began the drawdown of the war on terror's first phase."},
{d:"2011-07-09",t:"South Sudan independence",c:"pol",i:3,r:"Africa",s:"The world's newest country seceded after decades of war, then fell into civil war of its own within two years."},
{d:"2012-07-26",t:"'Whatever it takes'",c:"econ",i:2,r:"Europe",s:"Mario Draghi's three words halted the euro's breakup without spending a cent, the most effective central-bank intervention on record."},
{d:"2012-11-15",t:"Xi Jinping takes power",c:"pol",i:1,r:"Asia",s:"Took over the Communist Party, and the presidency four months later; an anti-corruption drive, the abolition of term limits and Belt and Road turned China toward personalised rule and global assertiveness."},
{d:"2014-02-20",t:"Maidan revolution",c:"pol",i:2,r:"Europe",s:"Ukraine's president fled after protests and sniper killings in Kyiv, triggering Russia's intervention."},
{d:"2014-03-18",t:"Russia annexes Crimea",c:"war",i:1,r:"Europe",s:"The first forcible annexation of European territory since 1945 brought sanctions, war in the Donbas and the end of post-Cold-War security assumptions."},
{d:"2014-06-29",t:"Islamic State declares caliphate",c:"war",i:2,r:"MidEast",s:"After seizing Mosul, ISIS controlled territory the size of Britain, drew in a global coalition and inspired attacks across Europe."},
{d:"2014-11",t:"Oil price collapse",c:"econ",i:2,r:"Global",s:"OPEC declined to cut output against US shale; crude fell from $110 to under $30, straining Russia, Venezuela and Nigeria."},
{d:"2015-04",t:"European migration crisis",c:"pol",i:2,r:"Europe",s:"Over a million people crossed the Mediterranean, mostly from Syria; the response strained EU unity and fuelled populist parties across the continent."},
{d:"2015-07-14",t:"Iran nuclear deal",c:"pol",i:2,r:"MidEast",s:"Sanctions relief in exchange for verified limits on enrichment — a rare arms-control success, abandoned by the US in 2018."},
{d:"2015-12-12",t:"Paris Climate Agreement",c:"pol",i:1,r:"Global",s:"Nearly 200 countries agreed to hold warming well below 2°C through national pledges, the first universal climate accord."},
{d:"2016-06-23",t:"Brexit referendum",c:"pol",i:1,r:"Europe",s:"Britain voted 52–48 to leave the EU, the first member state to do so, and opened a decade of constitutional and trade renegotiation."},
{d:"2016-11-08",t:"Trump elected",c:"pol",i:1,r:"Americas",s:"A victory built on trade scepticism and immigration restriction ended the bipartisan consensus on globalisation and alliances."},
{d:"2018-03-22",t:"US–China trade war",c:"econ",i:2,r:"Global",s:"Tariffs on hundreds of billions of goods began the decoupling of the world's two largest economies and the return of industrial policy."},
{d:"2019-06-09",t:"Hong Kong protests",c:"pol",i:2,r:"Asia",s:"Millions marched against an extradition bill; Beijing answered with a national security law in 2020 that ended the territory's autonomy."},

// ── 2020s ──────────────────────────────────────────────────────────────────────
{d:"2020-01-30",t:"COVID-19 pandemic declared an emergency",c:"shock",i:1,r:"Global",s:"The WHO's emergency declaration preceded lockdowns across most of the world; the pandemic killed millions, and its fiscal and supply shocks still shape the 2020s."},
{d:"2020-03-09",t:"COVID market crash",c:"econ",i:2,r:"Global",s:"The fastest bear market on record was met with unprecedented central-bank and fiscal support, an intervention that seeded the inflation of 2021–23."},
{d:"2020-01-31",t:"Brexit takes effect",c:"pol",i:2,r:"Europe",s:"Britain formally left the EU after 47 years of membership and three years of negotiation."},
{d:"2020-05-25",t:"George Floyd protests",c:"pol",i:2,r:"Americas",s:"A police killing filmed by a bystander set off the largest protest wave in US history and a global reckoning over race and policing."},
{d:"2021-01-06",t:"US Capitol attack",c:"pol",i:2,r:"Americas",s:"A mob stormed Congress to stop certification of the election, the first violent interruption of a US presidential transition."},
{d:"2021-08-15",t:"Taliban retake Kabul",c:"war",i:2,r:"Asia",s:"The Afghan government collapsed in days as US forces withdrew, ending twenty years of war and Western state-building."},
{d:"2022-02-24",t:"Russia invades Ukraine",c:"war",i:1,r:"Europe",s:"The largest war in Europe since 1945 brought sweeping sanctions, an energy shock, NATO's enlargement to Finland and Sweden, and a lasting realignment."},
{d:"2022-06",t:"Global inflation peak",c:"econ",i:2,r:"Global",s:"US inflation hit 9.1% and the euro area 10.6% as energy and supply shocks compounded pandemic stimulus, ending fifteen years of near-zero interest rates."},
{d:"2022-09-08",t:"Death of Elizabeth II",c:"pol",i:3,r:"Europe",s:"A seventy-year reign ended, closing the last direct link between the modern monarchy and the imperial era."},
{d:"2023-03-10",t:"Silicon Valley Bank fails",c:"econ",i:2,r:"Americas",s:"The fastest bank run in history, driven by rate losses and social media, triggered emergency guarantees and the collapse of Credit Suisse."},
{d:"2023-10-07",t:"Hamas attack and Gaza war",c:"war",i:1,r:"MidEast",s:"An assault killing about 1,200 Israelis triggered a war in Gaza with tens of thousands of Palestinian deaths, regional escalation and a global diplomatic rupture."},
{d:"2024",t:"The year of elections",c:"pol",i:2,r:"Global",s:"More than 70 countries and around half the world's population voted, and incumbents lost ground almost everywhere amid post-inflation discontent."},
{d:"2024-11-05",t:"Trump re-elected",c:"pol",i:1,r:"Americas",s:"A return to power on a platform of universal tariffs, mass deportation and executive consolidation, with implications for alliances and trade worldwide."},
{d:"2024-12-08",t:"Assad regime falls",c:"pol",i:1,r:"MidEast",s:"A rapid rebel offensive ended 54 years of Assad family rule in Syria, redrawing the balance among Russia, Iran, Turkey and the Gulf states."},
{d:"2025-04-02",t:"US tariff shock",c:"econ",i:1,r:"Global",s:"Sweeping across-the-board US tariffs — the steepest since the 1930s — jolted markets and forced trading partners into retaliation and renegotiation."},

// ── Second pass: depth and global coverage, 1900–1959 ──────────────────────────
{d:"1902-05-20",t:"Cuban independence",c:"pol",i:3,r:"Americas",s:"US occupation ended, but the Platt Amendment reserved Washington's right to intervene — the pattern of formal independence under American tutelage."},
{d:"1903-04-19",t:"Kishinev pogrom",c:"shock",i:3,r:"Europe",s:"A two-day massacre in Bessarabia drove mass Jewish emigration to America and Palestine and galvanised political Zionism."},
{d:"1903-06-16",t:"Ford Motor Company founded",c:"econ",i:3,r:"Americas",s:"The firm that would make the car a mass-market product rather than a rich man's toy."},
{d:"1904-01-12",t:"Herero and Nama genocide",c:"shock",i:2,r:"Africa",s:"German colonial forces drove the Herero into the desert and ran death camps in South West Africa, killing up to 80% of the population — often called the century's first genocide."},
{d:"1906-04-18",t:"San Francisco earthquake",c:"shock",i:3,r:"Americas",s:"The quake and fire destroyed a major city; insurance payments drained gold from London and helped set up the Panic of 1907."},
{d:"1908-10-01",t:"Ford Model T",c:"econ",i:2,r:"Americas",s:"Standardised, affordable and endlessly repairable, it created mass motoring and, with the moving assembly line of 1913, modern mass production."},
{d:"1911-05-15",t:"Standard Oil broken up",c:"econ",i:2,r:"Americas",s:"The Supreme Court dissolved Rockefeller's monopoly into 34 companies, establishing that antitrust law could dismantle a dominant firm."},
{d:"1912-04-15",t:"Titanic sinks",c:"shock",i:3,r:"Global",s:"1,500 died for want of lifeboats; the disaster produced the first international maritime safety convention."},
{d:"1913-12",t:"Moving assembly line",c:"econ",i:2,r:"Americas",s:"Ford cut chassis assembly from twelve hours to ninety minutes, then doubled wages — the productivity bargain at the heart of the consumer economy."},
{d:"1916-05-31",t:"Battle of Jutland",c:"war",i:3,r:"Europe",s:"The war's only great fleet action was tactically inconclusive but left the British blockade intact, which slowly strangled Germany."},
{d:"1919-05",t:"Red Summer",c:"pol",i:3,r:"Americas",s:"White mobs attacked Black communities in dozens of US cities; the violence met organised armed resistance and pushed the NAACP to national prominence."},
{d:"1920-01-02",t:"Palmer Raids",c:"pol",i:3,r:"Americas",s:"Mass arrests and deportations of suspected radicals in the first Red Scare, a template for later loyalty panics."},
{d:"1921-11-12",t:"Washington Naval Conference",c:"pol",i:2,r:"Global",s:"The first successful arms-limitation treaty capped battleship tonnage among the major navies and held for a decade."},
{d:"1921-12-06",t:"Anglo-Irish Treaty",c:"pol",i:2,r:"Europe",s:"Created the Irish Free State and partitioned the island, splitting the independence movement into a civil war."},
{d:"1922-11-01",t:"Ottoman sultanate abolished",c:"pol",i:2,r:"MidEast",s:"Six centuries of Ottoman rule ended; the caliphate followed in 1924, leaving a vacancy Islamists have invoked ever since."},
{d:"1923-09-01",t:"Great Kantō earthquake",c:"shock",i:3,r:"Asia",s:"Killed some 105,000 and destroyed Tokyo and Yokohama; the reconstruction debt strained Japanese banks for a decade, and vigilante massacres of Koreans followed."},
{d:"1924-05-26",t:"US Immigration Act",c:"pol",i:2,r:"Americas",s:"National-origin quotas cut southern and eastern European arrivals and barred Asians almost entirely, closing the era of open American immigration for forty years."},
{d:"1925-04-28",t:"Britain returns to gold",c:"econ",i:2,r:"Europe",s:"Churchill restored the pre-war parity; the overvalued pound crushed exports and coal wages, leading to the General Strike."},
{d:"1926-04-25",t:"Reza Shah crowned",c:"pol",i:3,r:"MidEast",s:"Founded the Pahlavi dynasty and began the forced modernisation of Iran that his son continued until 1979."},
{d:"1927-11-12",t:"Trotsky expelled",c:"pol",i:3,r:"Europe",s:"Stalin's defeat of the Left Opposition ended collective leadership and cleared the way for forced collectivisation."},
{d:"1929-02-11",t:"Lateran Treaty",c:"pol",i:3,r:"Europe",s:"Mussolini settled the papacy's 59-year dispute with the Italian state and created Vatican City, buying the regime Catholic acquiescence."},
{d:"1930-10-24",t:"Vargas takes power in Brazil",c:"pol",i:2,r:"Americas",s:"A revolution ended the coffee oligarchy and began fifteen years of centralising, industrialising authoritarian rule that shaped modern Brazil."},
{d:"1931-05-11",t:"Creditanstalt collapse",c:"econ",i:2,r:"Europe",s:"The failure of Austria's largest bank spread panic through central Europe, forcing Germany off gold and turning a recession into the Depression."},
{d:"1931-12-11",t:"Statute of Westminster",c:"pol",i:2,r:"Global",s:"Gave the dominions full legislative independence, converting the British Empire into a commonwealth of sovereign states."},
{d:"1932-06-15",t:"Chaco War",c:"war",i:3,r:"Americas",s:"Bolivia and Paraguay fought the bloodiest South American war of the century over land wrongly believed to hold oil."},
{d:"1932-07-21",t:"Imperial preference at Ottawa",c:"econ",i:3,r:"Global",s:"Britain abandoned free trade for an imperial tariff bloc, hardening the division of the world economy into currency and trade zones."},
{d:"1933-04-05",t:"US leaves the gold standard",c:"econ",i:2,r:"Americas",s:"Roosevelt banned private gold holdings and devalued the dollar, freeing monetary policy and beginning recovery."},
{d:"1934-06-30",t:"Night of the Long Knives",c:"pol",i:3,r:"Europe",s:"Hitler had the SA leadership murdered, securing the army's loyalty and confirming that the regime would kill without legal process."},
{d:"1935-08-02",t:"Government of India Act",c:"pol",i:3,r:"Asia",s:"Granted provincial autonomy while withholding real power at the centre — too little to satisfy Congress, and the framework India's 1950 constitution built on."},
{d:"1936-11-25",t:"Anti-Comintern Pact",c:"pol",i:3,r:"Global",s:"Germany and Japan aligned against the Soviet Union, with Italy joining a year later — the diplomatic skeleton of the Axis."},
{d:"1937-08",t:"Roosevelt recession",c:"econ",i:3,r:"Americas",s:"Premature budget tightening and monetary contraction sent output down sharply again, the classic warning against withdrawing stimulus too early."},
{d:"1938-03-18",t:"Mexico nationalises oil",c:"econ",i:2,r:"Americas",s:"Cárdenas expropriated foreign oil companies and created Pemex, the first successful resource nationalisation and a model across the developing world."},
{d:"1939-11-30",t:"Winter War",c:"war",i:3,r:"Europe",s:"Finland's resistance to Soviet invasion cost Moscow enormous casualties and convinced Hitler the Red Army could be beaten."},
{d:"1940-04",t:"Katyn massacre",c:"shock",i:3,r:"Europe",s:"Soviet secret police executed some 22,000 Polish officers and officials; the lie about it poisoned Polish–Soviet relations for fifty years."},
{d:"1940-09-27",t:"Tripartite Pact",c:"pol",i:3,r:"Global",s:"Germany, Italy and Japan formalised the Axis, tying the European and Asian wars into one conflict."},
{d:"1941-09-08",t:"Siege of Leningrad",c:"war",i:2,r:"Europe",s:"872 days of encirclement killed perhaps a million civilians, mostly by starvation — the deadliest siege in history."},
{d:"1942-08-08",t:"Quit India Movement",c:"pol",i:2,r:"Asia",s:"Congress demanded immediate independence and its leadership was jailed; British authority in India never recovered."},
{d:"1943-11-28",t:"Tehran Conference",c:"pol",i:3,r:"MidEast",s:"The Big Three met for the first time, agreeing a second front in France and sketching the post-war spheres."},
{d:"1944-08-01",t:"Warsaw Uprising",c:"war",i:3,r:"Europe",s:"The Home Army rose as the Red Army halted across the river; 200,000 died and Poland's independent leadership was destroyed before liberation."},
{d:"1945-03-22",t:"Arab League founded",c:"pol",i:3,r:"MidEast",s:"Six states created the first pan-Arab body, which coordinated opposition to partition in Palestine three years later."},
{d:"1945-07-17",t:"Potsdam Conference",c:"pol",i:2,r:"Europe",s:"The victors set Germany's occupation and Poland's new borders as relations cooled; Truman learned of the atomic test mid-conference."},
{d:"1945-08-17",t:"Indonesia declares independence",c:"pol",i:2,r:"Asia",s:"Sukarno proclaimed a republic days after Japan's surrender, beginning four years of war against Dutch reconquest."},
{d:"1945-09-02",t:"Vietnam declares independence",c:"pol",i:3,r:"Asia",s:"Ho Chi Minh quoted the American Declaration in Hanoi; France's refusal to accept it led to thirty years of war."},
{d:"1946-07-04",t:"Philippine independence",c:"pol",i:3,r:"Asia",s:"The US granted independence on schedule, retaining bases and trade preferences — a comparatively orderly decolonisation."},
{d:"1946-10-01",t:"Nuremberg verdicts",c:"pol",i:3,r:"Europe",s:"Twelve death sentences and the documentary record of the Holocaust made denial untenable and set the precedent for later tribunals."},
{d:"1946-12-19",t:"First Indochina War",c:"war",i:2,r:"Asia",s:"Fighting between France and the Viet Minh began eight years of war that ended at Dien Bien Phu and drew the US in behind it."},
{d:"1947-10-22",t:"First Kashmir war",c:"war",i:2,r:"Asia",s:"India and Pakistan fought over the princely state within weeks of independence, freezing a dispute that has produced three more wars and two nuclear arsenals."},
{d:"1948-01-04",t:"Burmese independence",c:"pol",i:3,r:"Asia",s:"Burma left the Commonwealth entirely and fell almost immediately into ethnic insurgencies that continue today."},
{d:"1948-01-30",t:"Gandhi assassinated",c:"pol",i:2,r:"Asia",s:"Killed by a Hindu nationalist five months after independence, a warning about the forces partition had unleashed."},
{d:"1948-04-16",t:"OEEC founded",c:"econ",i:3,r:"Europe",s:"Set up to administer Marshall aid, it became the habit of economic cooperation that grew into the OECD."},
{d:"1949-01-25",t:"Comecon founded",c:"econ",i:3,r:"Europe",s:"Moscow's answer to the Marshall Plan organised trade within the Eastern bloc on political rather than price terms."},
{d:"1949-09-18",t:"Sterling devaluation",c:"econ",i:3,r:"Europe",s:"A 30% devaluation against the dollar, copied by two dozen countries, confirmed the dollar's postwar dominance."},
{d:"1949-12-27",t:"Dutch recognise Indonesia",c:"pol",i:3,r:"Asia",s:"Four years of colonial war ended under heavy American pressure, creating the world's fourth most populous country."},
{d:"1950-05-09",t:"Schuman Declaration",c:"pol",i:2,r:"Europe",s:"Proposed pooling Franco-German coal and steel to make war 'materially impossible' — the founding text of European integration."},
{d:"1950-10-07",t:"China takes Tibet",c:"pol",i:3,r:"Asia",s:"The People's Liberation Army entered Tibet, a claim that still shapes Chinese domestic policy and its border dispute with India."},
{d:"1951-04-28",t:"Iran nationalises oil",c:"econ",i:2,r:"MidEast",s:"Mossadegh took over the Anglo-Iranian Oil Company; a British boycott and the 1953 coup followed, but the precedent stood."},
{d:"1951-09-08",t:"San Francisco Peace Treaty",c:"pol",i:2,r:"Asia",s:"Ended the occupation of Japan on lenient terms and tied Tokyo to Washington by a security treaty that still anchors Asian security."},
{d:"1952-04-09",t:"Bolivian National Revolution",c:"pol",i:3,r:"Americas",s:"Nationalised the tin mines, redistributed land and gave the vote to the indigenous majority, the most radical Latin American change before Cuba."},
{d:"1953-06-17",t:"East German uprising",c:"pol",i:3,r:"Europe",s:"Workers' protests over quotas were crushed by Soviet tanks, the first revolt against communist rule in the bloc."},
{d:"1954-06-27",t:"Guatemala coup",c:"pol",i:2,r:"Americas",s:"A CIA operation removed the elected Árbenz government after land reform touched United Fruit, beginning 36 years of civil war and setting the Cold War pattern in Latin America."},
{d:"1955-05-15",t:"Austrian State Treaty",c:"pol",i:3,r:"Europe",s:"The occupying powers withdrew in exchange for permanent neutrality — the only Cold War case of a Soviet military withdrawal from a European country."},
{d:"1956-01-01",t:"Sudanese independence",c:"pol",i:3,r:"Africa",s:"Independence from Anglo-Egyptian rule came with a north–south divide that produced two civil wars and eventual partition."},
{d:"1957-08-31",t:"Malayan independence",c:"pol",i:3,r:"Asia",s:"Britain handed over after defeating a communist insurgency, and the multi-ethnic bargain struck then still structures Malaysian politics."},
{d:"1958-02-01",t:"United Arab Republic",c:"pol",i:3,r:"MidEast",s:"Egypt and Syria merged under Nasser at the height of pan-Arabism; the union collapsed in three years."},
{d:"1958-07-14",t:"Iraqi Revolution",c:"pol",i:2,r:"MidEast",s:"The Hashemite monarchy was overthrown and killed, ending Britain's Baghdad Pact system and beginning the instability that produced Saddam."},
{d:"1959-03-10",t:"Tibetan uprising",c:"pol",i:3,r:"Asia",s:"The Dalai Lama fled to India after a failed revolt, creating an exile community and a lasting irritant in Sino-Indian relations."},
{d:"1959-12-01",t:"Antarctic Treaty",c:"pol",i:3,r:"Global",s:"Reserved a continent for science and banned military activity — an unusual Cold War success in shared governance."},

// ── Second pass: depth and global coverage, 1960–1999 ──────────────────────────
{d:"1960-05-01",t:"U-2 incident",c:"pol",i:3,r:"Europe",s:"A downed American spy plane and Eisenhower's denial wrecked the Paris summit and froze the first thaw."},
{d:"1960-06-30",t:"Congo crisis",c:"pol",i:2,r:"Africa",s:"Independence collapsed within days into secession and mutiny; Lumumba's murder and Mobutu's rise made Congo the Cold War's African battleground."},
{d:"1961-04-11",t:"Eichmann trial",c:"pol",i:3,r:"MidEast",s:"Televised testimony in Jerusalem put the Holocaust before a global audience and reframed how it was remembered."},
{d:"1961-09-01",t:"Non-Aligned Movement",c:"pol",i:3,r:"Europe",s:"Twenty-five states met in Belgrade to organise a bloc refusing both superpowers, giving newly independent countries collective weight."},
{d:"1962-07-05",t:"Algerian independence",c:"pol",i:2,r:"Africa",s:"Eight years of war ended with independence and the flight of a million European settlers, transforming both Algeria and France."},
{d:"1962-10-20",t:"Sino-Indian War",c:"war",i:3,r:"Asia",s:"A month-long Himalayan war humiliated India, pushed it toward Soviet arms, and left a border still contested today."},
{d:"1963-05-25",t:"Organisation of African Unity",c:"pol",i:3,r:"Africa",s:"Newly independent states agreed to keep colonial borders — a decision that prevented endless border wars while locking in arbitrary lines."},
{d:"1963-12-12",t:"Kenyan independence",c:"pol",i:3,r:"Africa",s:"Came after the Mau Mau emergency, in which British forces used detention camps and torture that London only acknowledged in 2013."},
{d:"1964-03-31",t:"Brazilian coup",c:"pol",i:2,r:"Americas",s:"With US backing, the military seized power for 21 years, the start of a wave of Southern Cone dictatorships."},
{d:"1964-05-28",t:"PLO founded",c:"pol",i:3,r:"MidEast",s:"Gave Palestinian nationalism an institutional voice independent of Arab governments."},
{d:"1964-06-12",t:"Mandela sentenced to life",c:"pol",i:2,r:"Africa",s:"The Rivonia trial jailed the ANC leadership; Mandela's dock speech became the movement's founding text."},
{d:"1965-11-11",t:"Rhodesia's UDI",c:"pol",i:3,r:"Africa",s:"A white minority government unilaterally declared independence, prompting sanctions and a fifteen-year bush war that ended in Zimbabwe."},
{d:"1966-01-15",t:"Nigerian coup",c:"pol",i:3,r:"Africa",s:"The first of many; a counter-coup and pogroms followed, leading directly to the Biafran war."},
{d:"1966-02-24",t:"Nkrumah overthrown",c:"pol",i:3,r:"Africa",s:"Ghana's independence leader was deposed by the army, an early sign that African one-party states would give way to military rule."},
{d:"1967-08-08",t:"ASEAN founded",c:"pol",i:2,r:"Asia",s:"Five non-communist states formed a bloc to contain conflict among themselves; it became the framework for Southeast Asian diplomacy and trade."},
{d:"1967-10-09",t:"Che Guevara killed",c:"pol",i:3,r:"Americas",s:"Captured and shot in Bolivia, ending the strategy of exporting guerrilla revolution and creating an enduring political icon."},
{d:"1967-11-18",t:"Sterling devalued",c:"econ",i:3,r:"Europe",s:"Wilson's 'pound in your pocket' devaluation marked Britain's slide from reserve-currency status."},
{d:"1968-07-01",t:"Non-Proliferation Treaty",c:"pol",i:2,r:"Global",s:"Froze the nuclear club at five in exchange for disarmament promises and civil nuclear access — still the basis of every proliferation dispute."},
{d:"1968-10-02",t:"Tlatelolco massacre",c:"pol",i:3,r:"Americas",s:"Mexican troops killed hundreds of student protesters days before the Olympics, a turning point against one-party rule."},
{d:"1969-03-02",t:"Sino-Soviet border clashes",c:"war",i:2,r:"Asia",s:"Fighting on the Ussuri River confirmed the communist split and opened the diplomatic space Nixon used three years later."},
{d:"1969-09-01",t:"Gaddafi seizes power",c:"pol",i:2,r:"Africa",s:"A young officers' coup in Libya nationalised oil, funded militant movements worldwide and lasted 42 years."},
{d:"1970-09-16",t:"Black September",c:"war",i:3,r:"MidEast",s:"Jordan expelled the PLO after a near civil war, moving the Palestinian armed struggle to Lebanon."},
{d:"1970-09-28",t:"Death of Nasser",c:"pol",i:3,r:"MidEast",s:"Pan-Arabism's central figure died at 52; Sadat's succession turned Egypt toward the US and a separate peace."},
{d:"1971-01-25",t:"Idi Amin seizes Uganda",c:"pol",i:3,r:"Africa",s:"Eight years of terror, the expulsion of the Asian community and economic ruin followed."},
{d:"1971-12-18",t:"Smithsonian Agreement",c:"econ",i:3,r:"Global",s:"An attempt to rebuild fixed exchange rates after the Nixon shock collapsed within 15 months, leaving currencies floating for good."},
{d:"1972-01-30",t:"Bloody Sunday, Derry",c:"war",i:3,r:"Europe",s:"British paratroopers killed 14 civil-rights marchers, driving recruitment to the Provisional IRA and prolonging the Troubles."},
{d:"1972-09-05",t:"Munich Olympics massacre",c:"war",i:3,r:"Europe",s:"Eleven Israeli athletes died after a Palestinian attack at the Games, internationalising both terrorism and counter-terrorism."},
{d:"1974-05-18",t:"India's first nuclear test",c:"war",i:2,r:"Asia",s:"'Smiling Buddha' broke the non-proliferation regime's containment and triggered Pakistan's parallel programme."},
{d:"1974-07-20",t:"Turkey invades Cyprus",c:"war",i:2,r:"Europe",s:"Partitioned the island after a Greek-backed coup; the division persists and still blocks Turkey's EU path."},
{d:"1974-09-12",t:"Ethiopian revolution",c:"pol",i:2,r:"Africa",s:"The Derg deposed Haile Selassie, ending a dynasty claiming descent from Solomon and beginning famine, terror and civil war."},
{d:"1975-04-13",t:"Lebanese civil war",c:"war",i:2,r:"MidEast",s:"Fifteen years of sectarian war destroyed the Middle East's most cosmopolitan state and drew in Israel, Syria and the US."},
{d:"1975-11-11",t:"Angola and Mozambique independent",c:"pol",i:2,r:"Africa",s:"Portugal's withdrawal left proxy civil wars fought with Cuban, Soviet, South African and American support for two more decades."},
{d:"1975-12-07",t:"Indonesia invades East Timor",c:"war",i:3,r:"Asia",s:"A 24-year occupation followed in which perhaps a third of the population died, ending only with the 1999 referendum."},
{d:"1976-03-24",t:"Argentine coup",c:"pol",i:2,r:"Americas",s:"The junta's 'dirty war' disappeared some 30,000 people, part of the cross-border Operation Condor."},
{d:"1976-06-16",t:"Soweto uprising",c:"pol",i:2,r:"Africa",s:"Police fired on schoolchildren protesting instruction in Afrikaans; the images made apartheid an international pariah cause."},
{d:"1977-01-01",t:"Charter 77",c:"pol",i:3,r:"Europe",s:"Czechoslovak dissidents used the Helsinki human-rights language against their own government, the movement Václav Havel led into power in 1989."},
{d:"1977-07-05",t:"Zia's coup in Pakistan",c:"pol",i:3,r:"Asia",s:"Eleven years of military rule brought Islamisation of law and the alliance with the Afghan mujahideen."},
{d:"1977-11-19",t:"Sadat goes to Jerusalem",c:"pol",i:2,r:"MidEast",s:"The first Arab leader to address the Knesset broke a thirty-year taboo and made Camp David possible."},
{d:"1978-04-27",t:"Saur Revolution",c:"pol",i:3,r:"Asia",s:"A communist coup in Kabul provoked the rural revolt that drew in the Soviet Union eighteen months later."},
{d:"1979-02-17",t:"Sino-Vietnamese War",c:"war",i:3,r:"Asia",s:"China's punitive invasion after Vietnam toppled the Khmer Rouge ended in a costly stalemate."},
{d:"1979-07-19",t:"Sandinista revolution",c:"pol",i:2,r:"Americas",s:"Somoza's fall in Nicaragua brought a leftist government and the US-funded Contra war that dominated 1980s Latin American politics."},
{d:"1979-11-20",t:"Grand Mosque seizure",c:"pol",i:2,r:"MidEast",s:"Militants held Mecca for two weeks; the shaken Saudi monarchy responded by funding religious conservatism at home and abroad."},
{d:"1980-04-18",t:"Zimbabwean independence",c:"pol",i:3,r:"Africa",s:"Mugabe took power after the bush war, beginning 37 years of rule that ended in hyperinflation and a coup."},
{d:"1981-06-05",t:"AIDS first reported",c:"shock",i:2,r:"Global",s:"A CDC bulletin described five cases; the pandemic has since killed over 40 million and reshaped public health, patent law and activism."},
{d:"1981-10-06",t:"Sadat assassinated",c:"pol",i:2,r:"MidEast",s:"Islamists killed him for the peace with Israel; Mubarak's thirty-year emergency rule followed."},
{d:"1981-12-13",t:"Martial law in Poland",c:"pol",i:2,r:"Europe",s:"Jaruzelski interned Solidarity's leaders to pre-empt Soviet invasion, driving the opposition underground for eight years."},
{d:"1982-06-06",t:"Israel invades Lebanon",c:"war",i:2,r:"MidEast",s:"The siege of Beirut expelled the PLO but led to the Sabra and Shatila massacres and the birth of Hezbollah."},
{d:"1983-09-01",t:"Korean Air Flight 007",c:"pol",i:3,r:"Asia",s:"A Soviet fighter shot down a straying airliner with 269 aboard, deepening the era's mutual fear — and prompting the US to open GPS to civilians."},
{d:"1983-10-23",t:"Beirut barracks bombing",c:"war",i:2,r:"MidEast",s:"Suicide truck bombs killed 241 US and 58 French personnel, forcing Western withdrawal and demonstrating the tactic's strategic power."},
{d:"1983-11-02",t:"Able Archer war scare",c:"war",i:3,r:"Europe",s:"A NATO command exercise was misread in Moscow as cover for a first strike, one of the closest brushes with nuclear war."},
{d:"1984-03-06",t:"UK miners' strike",c:"econ",i:3,r:"Europe",s:"A year-long strike ended in total defeat, breaking organised labour's power in Britain and confirming the deindustrialising turn."},
{d:"1984-10",t:"Ethiopian famine",c:"shock",i:2,r:"Africa",s:"Drought compounded by war and forced resettlement killed hundreds of thousands and made televised famine relief a permanent feature of Western politics."},
{d:"1986-02-17",t:"Single European Act",c:"econ",i:2,r:"Europe",s:"Set a 1992 deadline for a genuine single market and expanded majority voting, the biggest step of integration between Rome and Maastricht."},
{d:"1986-11-03",t:"Iran–Contra affair",c:"pol",i:3,r:"Americas",s:"Arms secretly sold to Iran funded Nicaraguan rebels in defiance of Congress, the gravest scandal of the Reagan years."},
{d:"1988-03-16",t:"Halabja chemical attack",c:"shock",i:2,r:"MidEast",s:"Iraq gassed a Kurdish town, killing thousands — the largest chemical attack on civilians ever, and later a justification for war."},
{d:"1988-05-15",t:"Soviets begin Afghan withdrawal",c:"war",i:2,r:"Asia",s:"Nine years of war had cost 15,000 Soviet dead and immense prestige; the retreat signalled the empire's limits."},
{d:"1988-08-20",t:"Iran–Iraq ceasefire",c:"war",i:2,r:"MidEast",s:"Eight years of war ended roughly where they began, leaving Iraq indebted and looking at Kuwait's oil."},
{d:"1988-12-21",t:"Lockerbie bombing",c:"war",i:3,r:"Europe",s:"270 died when a Pan Am jet was destroyed over Scotland; Libya's eventual admission underpinned its 2003 rapprochement."},
{d:"1989-06-04",t:"Poland's semi-free election",c:"pol",i:2,r:"Europe",s:"Solidarity won every seat it was allowed to contest, producing the bloc's first non-communist government and showing the rest of Eastern Europe what was possible."},
{d:"1989-11-17",t:"Velvet Revolution",c:"pol",i:2,r:"Europe",s:"Ten days of protest ended communist rule in Czechoslovakia without bloodshed, with Havel president by December."},
{d:"1989-12-29",t:"Nikkei peaks",c:"econ",i:2,r:"Asia",s:"The index closed at 38,915 on the year's last trading day — a level not seen again for 34 years."},
{d:"1990-03-21",t:"Namibian independence",c:"pol",i:3,r:"Africa",s:"Africa's last colony became independent after a UN-supervised transition, a rehearsal for South Africa's own settlement."},
{d:"1991-07-01",t:"Warsaw Pact dissolved",c:"pol",i:3,r:"Europe",s:"The Soviet alliance disbanded itself, leaving NATO without an opponent and Eastern Europe seeking membership in it."},
{d:"1991-08-19",t:"Soviet August coup",c:"pol",i:2,r:"Europe",s:"Hardliners detained Gorbachev; Yeltsin's defiance from a tank broke the coup in three days and destroyed the party's authority."},
{d:"1992-04-06",t:"Bosnian War",c:"war",i:2,r:"Europe",s:"Three years of siege and ethnic cleansing killed some 100,000 and produced Europe's worst atrocities since 1945."},
{d:"1992-06-03",t:"Rio Earth Summit",c:"pol",i:2,r:"Global",s:"Created the climate and biodiversity conventions, the framework under which every later climate negotiation has taken place."},
{d:"1993-01-01",t:"EU single market",c:"econ",i:2,r:"Europe",s:"Free movement of goods, services, capital and people took effect across twelve countries, the deepest economic integration ever attempted between sovereign states."},
{d:"1993-01-01",t:"Czechoslovakia splits",c:"pol",i:3,r:"Europe",s:"The Velvet Divorce created the Czech Republic and Slovakia peacefully — the counter-example to Yugoslavia."},
{d:"1993-09-13",t:"Oslo Accords",c:"pol",i:1,r:"MidEast",s:"Mutual recognition and a handshake on the White House lawn created the Palestinian Authority and a five-year path to final status that was never completed."},
{d:"1993-10-03",t:"Russian constitutional crisis",c:"pol",i:3,r:"Europe",s:"Yeltsin shelled his own parliament and then wrote a constitution with a dominant presidency — the office Putin inherited."},
{d:"1994-01-01",t:"Zapatista uprising",c:"pol",i:3,r:"Americas",s:"Indigenous rebels rose in Chiapas on the day NAFTA took effect, becoming the first internet-savvy anti-globalisation movement."},
{d:"1995-02-26",t:"Barings Bank collapses",c:"econ",i:3,r:"Asia",s:"One trader's hidden derivatives losses destroyed a 233-year-old bank, forcing a rethink of trading controls."},
{d:"1995-03-26",t:"Schengen takes effect",c:"pol",i:2,r:"Europe",s:"Border checks disappeared between seven countries, making free movement tangible — and later a target of populist politics."},
{d:"1995-11-04",t:"Rabin assassinated",c:"pol",i:2,r:"MidEast",s:"An Israeli extremist killed the prime minister at a peace rally, removing the leader most able to deliver on Oslo."},
{d:"1996-08-31",t:"First Chechen war ends",c:"war",i:3,r:"Europe",s:"A humiliating settlement after 80,000 deaths exposed the Russian army's decay and set up the second war that made Putin's name."},
{d:"1996-09-24",t:"Comprehensive Test Ban Treaty",c:"pol",i:2,r:"Global",s:"Opened for signature and observed almost universally in practice, though never formally in force."},
{d:"1996-09-27",t:"Taliban take Kabul",c:"pol",i:2,r:"Asia",s:"A movement of religious students imposed severe rule on most of Afghanistan and gave al-Qaeda a base."},
{d:"1997-12-11",t:"Kyoto Protocol",c:"pol",i:2,r:"Global",s:"The first binding emissions targets — rejected by the US and imposing nothing on developing countries, but the template for Paris."},
{d:"1998-05-11",t:"India and Pakistan test nuclear weapons",c:"war",i:2,r:"Asia",s:"Five Indian tests and six Pakistani ones in three weeks made South Asia the first region with two hostile nuclear neighbours sharing a disputed border."},
{d:"1998-05-21",t:"Suharto resigns",c:"pol",i:2,r:"Asia",s:"The financial crisis and mass protest ended 32 years of rule, and Indonesia became a democracy of 200 million people."},
{d:"1998-08-07",t:"US embassy bombings",c:"war",i:3,r:"Africa",s:"Simultaneous attacks in Nairobi and Dar es Salaam killed 224 and introduced al-Qaeda to American counter-terrorism."},
{d:"1999-02-02",t:"Chávez takes office",c:"pol",i:2,r:"Americas",s:"Began two decades of oil-funded 'Bolivarian' socialism, a wave of left governments across Latin America, and eventual economic collapse."},
{d:"1999-08-30",t:"East Timor referendum",c:"pol",i:3,r:"Asia",s:"An overwhelming independence vote was met with militia violence, then an Australian-led intervention and UN administration."},
{d:"1999-11-30",t:"Seattle WTO protests",c:"econ",i:3,r:"Americas",s:"Tens of thousands shut down a trade summit, announcing an anti-globalisation politics that has since gone mainstream on both left and right."},

// ── Second pass: depth and global coverage, 2000–2026 ──────────────────────────
{d:"2000-03-26",t:"Putin elected president",c:"pol",i:3,r:"Europe",s:"Won on the back of the second Chechen war, beginning the consolidation of media, oligarchs and regional governors under the Kremlin."},
{d:"2000-09-28",t:"Second Intifada",c:"war",i:2,r:"MidEast",s:"Five years of suicide bombings and reoccupation killed some 4,000 people, destroyed the Israeli peace camp and buried the Oslo framework."},
{d:"2000-10-05",t:"Milošević falls",c:"pol",i:2,r:"Europe",s:"Mass protest over a stolen election ended his rule; he was later the first head of state tried by an international tribunal."},
{d:"2001-12-02",t:"Enron collapses",c:"econ",i:2,r:"Americas",s:"Accounting fraud destroyed a $60 billion company and its auditor, producing Sarbanes–Oxley and a lasting distrust of corporate reporting."},
{d:"2002-07-09",t:"African Union founded",c:"pol",i:2,r:"Africa",s:"Replaced the OAU with a body claiming the right to intervene against genocide, and a continental agenda of integration."},
{d:"2002-10-12",t:"Bali bombings",c:"war",i:3,r:"Asia",s:"202 killed by Jemaah Islamiyah, showing that al-Qaeda-linked networks operated far beyond the Middle East."},
{d:"2003-11-23",t:"Rose Revolution",c:"pol",i:3,r:"Europe",s:"Georgia's peaceful overthrow of a rigged election began the 'colour revolutions' that Moscow came to see as Western-engineered threats."},
{d:"2003-02",t:"Darfur conflict",c:"shock",i:2,r:"Africa",s:"Government-backed militias killed some 300,000 and displaced millions; the first ICC arrest warrant for a sitting head of state followed."},
{d:"2004-03-11",t:"Madrid train bombings",c:"war",i:3,r:"Europe",s:"191 killed three days before an election that unseated the government and led Spain to withdraw from Iraq."},
{d:"2005-05-29",t:"EU constitution rejected",c:"pol",i:3,r:"Europe",s:"French and Dutch voters killed the treaty, the first clear sign that integration had outrun public consent."},
{d:"2005-08-29",t:"Hurricane Katrina",c:"shock",i:2,r:"Americas",s:"1,800 died and a major city was evacuated; the failed response became a lasting symbol of state incapacity and racial inequality."},
{d:"2005-11-22",t:"Merkel becomes chancellor",c:"pol",i:2,r:"Europe",s:"Sixteen years in office made her the decisive figure in the euro crisis, the 2015 migration crisis and Europe's relations with Russia and China."},
{d:"2006-07-12",t:"Lebanon War",c:"war",i:3,r:"MidEast",s:"A month of fighting between Israel and Hezbollah ended inconclusively and confirmed the rise of non-state military power."},
{d:"2006-10-09",t:"North Korea's first nuclear test",c:"war",i:2,r:"Asia",s:"Made Pyongyang the ninth nuclear-armed state and demonstrated the limits of sanctions and six-party diplomacy."},
{d:"2006-12-30",t:"Saddam Hussein executed",c:"pol",i:3,r:"MidEast",s:"A sectarian-tinged hanging that deepened Iraq's civil war rather than closing it."},
{d:"2007-12-13",t:"Lisbon Treaty",c:"pol",i:2,r:"Europe",s:"Salvaged most of the rejected constitution, creating a permanent Council president and a foreign-policy chief."},
{d:"2008-06",t:"Global food price crisis",c:"econ",i:2,r:"Global",s:"Grain prices doubled, pushing 100 million into hunger and setting off riots in over 30 countries — a precursor of the Arab Spring."},
{d:"2008-08-08",t:"Beijing Olympics",c:"pol",i:3,r:"Asia",s:"A $40 billion display of arrival, staged weeks before the Western financial system nearly collapsed."},
{d:"2009-01-03",t:"Bitcoin's first block",c:"econ",i:3,r:"Global",s:"Launched with a headline about bank bailouts embedded in it; cryptocurrency grew into a trillion-dollar asset class and a regulatory problem."},
{d:"2009-06-13",t:"Iran's Green Movement",c:"pol",i:3,r:"MidEast",s:"Mass protest over a disputed election was crushed, but showed how social media could organise dissent — a lesson learned in Tunis eighteen months later."},
{d:"2010-04-20",t:"Deepwater Horizon",c:"shock",i:3,r:"Americas",s:"The largest marine oil spill in history cost BP over $65 billion and reshaped offshore drilling rules."},
{d:"2010-05-06",t:"Flash crash",c:"econ",i:3,r:"Americas",s:"The Dow fell 1,000 points and recovered within minutes, exposing how algorithmic trading had changed market structure."},
{d:"2011-08-05",t:"US credit rating downgraded",c:"econ",i:2,r:"Americas",s:"S&P cut the US from AAA after a debt-ceiling standoff, making fiscal brinkmanship a recurring market risk."},
{d:"2011-09-17",t:"Occupy Wall Street",c:"econ",i:3,r:"Americas",s:"The '99%' framing put inequality at the centre of Western politics for the next decade."},
{d:"2012-06-24",t:"Egypt's first free election",c:"pol",i:3,r:"MidEast",s:"Morsi's narrow win was the Arab Spring's only democratic transfer of power; the army removed him a year later."},
{d:"2013-05-22",t:"Taper tantrum",c:"econ",i:3,r:"Global",s:"A hint that the Fed would slow bond buying sent emerging-market currencies tumbling, showing how dependent the world had become on US liquidity."},
{d:"2013-06-05",t:"Snowden revelations",c:"pol",i:2,r:"Global",s:"Leaked documents exposed mass surveillance by the US and allies, straining alliances and reshaping the politics of privacy and encryption."},
{d:"2013-07-03",t:"Egyptian coup",c:"pol",i:2,r:"MidEast",s:"Sisi's removal of the elected president, and the killing of hundreds of protesters, ended the Arab Spring's democratic phase."},
{d:"2013-04-24",t:"Rana Plaza collapse",c:"econ",i:3,r:"Asia",s:"1,134 garment workers died in Bangladesh, forcing global brands to accept some responsibility for supply-chain conditions."},
{d:"2013-12",t:"Venezuela's economic collapse",c:"econ",i:2,r:"Americas",s:"Oil dependence, price controls and money-printing began a contraction of over 70% of GDP and the emigration of some 7 million people — the deepest peacetime collapse ever recorded."},
{d:"2014-03",t:"West Africa Ebola epidemic",c:"shock",i:2,r:"Africa",s:"11,000 deaths across Guinea, Liberia and Sierra Leone exposed the weakness of global outbreak response and prompted reforms used in 2020."},
{d:"2014-05-16",t:"Modi elected",c:"pol",i:2,r:"Asia",s:"The first single-party majority in India in thirty years brought Hindu-nationalist politics and an assertive foreign policy."},
{d:"2014-09-18",t:"Scottish independence referendum",c:"pol",i:3,r:"Europe",s:"A 55–45 vote to remain in the UK settled nothing for long — Brexit reopened the question two years later."},
{d:"2015-06-12",t:"Chinese stock crash",c:"econ",i:2,r:"Asia",s:"A margin-fuelled bubble lost a third of its value in weeks; the heavy-handed rescue raised doubts about Beijing's market management."},
{d:"2015-07-05",t:"Greek referendum and third bailout",c:"econ",i:2,r:"Europe",s:"Voters rejected austerity, and the government accepted harsher terms days later — the clearest demonstration of where power sat in the eurozone."},
{d:"2016-07-15",t:"Turkish coup attempt",c:"pol",i:2,r:"MidEast",s:"Its failure let Erdoğan purge over 100,000 officials and convert Turkey into an executive presidency."},
{d:"2016-11-24",t:"Colombian peace agreement",c:"pol",i:2,r:"Americas",s:"Ended 52 years of war with the FARC that killed 260,000 — signed after voters narrowly rejected a first version."},
{d:"2017-06-01",t:"US exits the Paris Agreement",c:"pol",i:2,r:"Global",s:"The world's second-largest emitter withdrew, testing whether the accord could survive without it; the US rejoined in 2021 and left again in 2025."},
{d:"2017-08-25",t:"Rohingya expulsion",c:"shock",i:2,r:"Asia",s:"Myanmar's army drove some 750,000 Rohingya into Bangladesh in weeks, the subject of an ongoing genocide case at the World Court."},
{d:"2017-10-01",t:"Catalan independence referendum",c:"pol",i:3,r:"Europe",s:"A banned vote met with police violence, a unilateral declaration and direct rule — Europe's sharpest secession crisis in decades."},
{d:"2017-11-21",t:"Mugabe ousted",c:"pol",i:3,r:"Africa",s:"A soft coup ended 37 years of rule after a decade of hyperinflation that reached inconceivable rates."},
{d:"2018-04-27",t:"Inter-Korean summit",c:"pol",i:3,r:"Asia",s:"The first crossing of the DMZ by a North Korean leader opened two years of summitry that produced no denuclearisation."},
{d:"2018-10-02",t:"Khashoggi killed",c:"pol",i:3,r:"MidEast",s:"A journalist murdered in a Saudi consulate; the muted international response marked the limits of human-rights pressure on energy suppliers."},
{d:"2019-04-11",t:"Bashir ousted in Sudan",c:"pol",i:2,r:"Africa",s:"Mass protest ended thirty years of rule; the promised civilian transition collapsed into war between rival generals in 2023."},
{d:"2019-05-30",t:"African free trade area",c:"econ",i:2,r:"Africa",s:"AfCFTA entered into force, creating the world's largest free-trade area by membership and a bid to raise intra-African trade above 15%."},
{d:"2019-08-05",t:"India revokes Kashmir's autonomy",c:"pol",i:2,r:"Asia",s:"Article 370 was abolished under a communications blackout, ending seventy years of special status and sharpening the dispute with Pakistan."},
{d:"2020-04-20",t:"Oil futures go negative",c:"econ",i:2,r:"Global",s:"Storage ran out during the pandemic collapse in demand and US crude settled at minus $37 — a price no model had contemplated."},
{d:"2020-06-30",t:"Hong Kong security law",c:"pol",i:2,r:"Asia",s:"Beijing criminalised secession and subversion, ending 'one country, two systems' 27 years early and prompting mass emigration."},
{d:"2020-09-15",t:"Abraham Accords",c:"pol",i:2,r:"MidEast",s:"The UAE and Bahrain normalised relations with Israel without a Palestinian settlement, redrawing regional alignments around Iran."},
{d:"2020-09-27",t:"Nagorno-Karabakh war",c:"war",i:2,r:"Asia",s:"Azerbaijan's drone-led victory over Armenia previewed how cheap drones would reshape conventional warfare."},
{d:"2020-12-08",t:"COVID vaccines deployed",c:"shock",i:2,r:"Global",s:"The first mRNA vaccinations came within a year of the genome being published — the fastest vaccine development in history, and unevenly distributed."},
{d:"2021-02-01",t:"Myanmar coup",c:"pol",i:2,r:"Asia",s:"The army annulled an election it lost, provoking a nationwide armed resistance and a civil war that continues."},
{d:"2021-09-15",t:"AUKUS pact",c:"pol",i:2,r:"Oceania",s:"A submarine and technology pact between Australia, the UK and US, aimed at China and at the cost of a rupture with France."},
{d:"2021-12",t:"Evergrande default",c:"econ",i:2,r:"Asia",s:"The collapse of China's most indebted developer began a property downturn that has weighed on the world's second-largest economy ever since."},
{d:"2022-05-18",t:"Finland and Sweden seek NATO membership",c:"pol",i:2,r:"Europe",s:"Two centuries of Swedish non-alignment and Finnish neutrality ended within months of Russia's invasion, doubling NATO's border with Russia."},
{d:"2022-07-09",t:"Sri Lanka's collapse",c:"econ",i:2,r:"Asia",s:"Default and fuel shortages drove protesters into the president's residence — the first of the post-pandemic debt crises in the developing world."},
{d:"2022-09-16",t:"Iran's 'Woman, Life, Freedom' protests",c:"pol",i:2,r:"MidEast",s:"Mahsa Amini's death in custody set off the most serious challenge to the Islamic Republic in decades, met with mass arrests and executions."},
{d:"2022-09-23",t:"UK mini-budget crisis",c:"econ",i:2,r:"Europe",s:"Unfunded tax cuts triggered a gilt collapse, a Bank of England rescue of pension funds and the shortest premiership in British history."},
{d:"2022-11-30",t:"ChatGPT and the AI boom",c:"econ",i:2,r:"Global",s:"Mass adoption of generative AI set off the largest capital-expenditure wave since the fibre build-out, reshaping equity markets, energy demand and industrial policy."},
{d:"2022-12-07",t:"China ends zero-COVID",c:"shock",i:2,r:"Asia",s:"Three years of lockdowns ended abruptly after nationwide protests, followed by a huge infection wave and a weakened growth model."},
{d:"2023-07-26",t:"Niger coup",c:"pol",i:2,r:"Africa",s:"The latest in a run of Sahel coups that expelled French and American forces and realigned the region toward Russia."},
{d:"2023-08-24",t:"BRICS expansion",c:"pol",i:2,r:"Global",s:"Six new members were invited, turning the grouping into a broader non-Western bloc and giving 'de-dollarisation' a diplomatic vehicle."},
{d:"2023-09-19",t:"Nagorno-Karabakh exodus",c:"war",i:2,r:"Asia",s:"Azerbaijan's one-day offensive ended the enclave and virtually its entire Armenian population left within a week."},
{d:"2023-12-10",t:"Milei takes office in Argentina",c:"econ",i:2,r:"Americas",s:"A libertarian economist won on a promise of shock therapy against 200% inflation, the most radical adjustment programme attempted in a democracy."},
{d:"2024-01",t:"Red Sea shipping attacks",c:"econ",i:2,r:"MidEast",s:"Houthi missiles pushed most container traffic around Africa, adding weeks to Asia–Europe routes and reviving supply-chain inflation fears."},
{d:"2024-03-19",t:"Japan ends negative rates",c:"econ",i:2,r:"Asia",s:"The last negative policy rate in the world was lifted after seventeen years, closing the era of ultra-cheap global money."},
{d:"2024-06-04",t:"Modi loses his majority",c:"pol",i:3,r:"Asia",s:"India's ruling party fell short and had to govern in coalition, a check on the decade's centralising trend."},
{d:"2024-07-04",t:"UK Labour landslide",c:"pol",i:3,r:"Europe",s:"Fourteen years of Conservative government ended with the party's worst defeat, on a low share of the vote in a fragmenting system."},
{d:"2024-12-03",t:"South Korea's martial law crisis",c:"pol",i:2,r:"Asia",s:"A president declared martial law overnight; parliament reversed it within hours and impeached him, testing a mature democracy's institutions in real time."},
{d:"2025-01-27",t:"DeepSeek shock",c:"econ",i:2,r:"Global",s:"A Chinese lab's low-cost model wiped hundreds of billions off AI-linked stocks in a day, questioning the assumption that frontier capability required frontier spending."},
{d:"2025-03-18",t:"Germany's fiscal turn",c:"econ",i:2,r:"Europe",s:"The Bundestag loosened the constitutional debt brake for defence and infrastructure, ending two decades of fiscal orthodoxy in Europe's largest economy."},

// ── 1600s ──────────────────────────────────────────────────────────────────────
{d:"1600-10-21",t:"Battle of Sekigahara",c:"war",i:1,r:"Asia",s:"Tokugawa Ieyasu's victory ended a century of civil war and made him master of Japan, opening 250 years of Tokugawa peace and isolation."},
{d:"1600-12-31",t:"English East India Company",c:"econ",i:1,r:"Global",s:"A royal charter gave a group of London merchants a monopoly on Asian trade; the company ended up governing India and became the model for the corporation as a political actor."},
{d:"1602-03-20",t:"Dutch East India Company founded",c:"econ",i:1,r:"Global",s:"The VOC merged rival Dutch ventures into the first company with permanently tradable shares, and was granted the power to wage war, coin money and sign treaties — a corporation with sovereign rights."},
{d:"1603-03-24",t:"Tokugawa shogunate established",c:"pol",i:2,r:"Asia",s:"Ieyasu took the title of shogun and moved the capital to Edo, beginning the regime that governed Japan until 1868."},
{d:"1603-03-24",t:"Union of the Crowns",c:"pol",i:3,r:"Europe",s:"James VI of Scotland inherited the English throne, joining the two kingdoms under one monarch a century before their parliaments merged."},
{d:"1607-05-14",t:"Jamestown founded",c:"pol",i:2,r:"Americas",s:"The first permanent English settlement in North America survived starvation and conflict with the Powhatan, and made tobacco the first colonial export staple."},
{d:"1608-07-03",t:"Quebec founded",c:"pol",i:3,r:"Americas",s:"Champlain's fur-trading post became the capital of New France and the root of French North America."},
{d:"1609-04-09",t:"Twelve Years' Truce",c:"pol",i:2,r:"Europe",s:"Spain agreed to a truce with the Dutch rebels, conceding in practice what it would not admit in law — and freeing the Republic to build its overseas empire."},
{d:"1609",t:"Bank of Amsterdam",c:"econ",i:2,r:"Europe",s:"A municipal bank offering safe deposits and clearing in a stable unit of account made Amsterdam the hub of European finance for a century."},
{d:"1613-07-21",t:"Romanov dynasty begins",c:"pol",i:2,r:"Europe",s:"Michael Romanov's election ended Russia's Time of Troubles and founded the dynasty that ruled until 1917."},
{d:"1618-05-23",t:"Thirty Years' War begins",c:"war",i:1,r:"Europe",s:"The Defenestration of Prague set off a religious and dynastic war that killed perhaps a third of the German population and drew in most of Europe."},
{d:"1619-05-30",t:"Batavia founded",c:"pol",i:2,r:"Asia",s:"The VOC razed Jayakarta and built its Asian capital on the site, the administrative centre of Dutch power in the East for 330 years and now Jakarta."},
{d:"1620-11-11",t:"Mayflower Compact",c:"pol",i:3,r:"Americas",s:"Separatist colonists agreed to govern themselves by majority consent, a text later read as a founding document of American self-government."},
{d:"1621-06-03",t:"Dutch West India Company",c:"econ",i:2,r:"Americas",s:"Chartered to attack Spanish and Portuguese trade in the Atlantic, the WIC ran privateering, the Brazilian sugar colonies, New Netherland and a large share of the Atlantic slave trade."},
{d:"1626-05",t:"Manhattan purchased",c:"econ",i:3,r:"Americas",s:"Peter Minuit's transaction with the Lenape — remembered, probably wrongly, as costing 60 guilders — founded New Amsterdam at the mouth of the Hudson."},
{d:"1628-09-08",t:"Piet Heyn takes the silver fleet",c:"war",i:3,r:"Americas",s:"The only capture of an entire Spanish treasure fleet funded a year of Dutch war and became a national legend."},
{d:"1630-02",t:"Dutch Brazil",c:"war",i:2,r:"Americas",s:"The WIC seized the sugar-producing northeast of Portuguese Brazil and held it for 24 years, running it with enslaved African labour before losing it to a settler revolt."},
{d:"1631-05-20",t:"Sack of Magdeburg",c:"war",i:3,r:"Europe",s:"Imperial troops destroyed a city of 25,000; the atrocity became the emblem of the Thirty Years' War's savagery."},
{d:"1637-02-03",t:"Tulip mania collapses",c:"econ",i:2,r:"Europe",s:"Bulb contracts that had reached the price of a house became unsellable within days — the first well-documented speculative bubble, and the reference point for every one since."},
{d:"1639-10-21",t:"Battle of the Downs",c:"war",i:3,r:"Europe",s:"Tromp destroyed a Spanish fleet in English waters, ending Spain's ability to reinforce Flanders by sea and confirming Dutch naval supremacy."},
{d:"1639-06",t:"Japan closes itself",c:"pol",i:2,r:"Asia",s:"The sakoku edicts expelled the Portuguese and barred Japanese from leaving; for two centuries the Dutch at Dejima were the only Europeans admitted."},
{d:"1640-12-01",t:"Portuguese Restoration",c:"pol",i:3,r:"Europe",s:"Portugal broke sixty years of union with Spain, and spent the following decades trying to recover colonies the Dutch had taken meanwhile."},
{d:"1641-01-14",t:"Dutch take Malacca",c:"war",i:2,r:"Asia",s:"The capture of the Portuguese fortress gave the VOC command of the strait between the Indian Ocean and the South China Sea."},
{d:"1641",t:"Dutch monopoly at Dejima",c:"econ",i:2,r:"Asia",s:"Confined to an artificial island in Nagasaki harbour, the VOC became Japan's only European trading partner — and, through 'Dutch learning', its only window on Western science."},
{d:"1642-08-22",t:"English Civil War begins",c:"war",i:1,r:"Europe",s:"King and Parliament went to war over taxation and religion; the outcome established that an English monarch governed on Parliament's terms."},
{d:"1644-04-25",t:"Fall of the Ming dynasty",c:"pol",i:1,r:"Asia",s:"Rebels took Beijing and the last Ming emperor hanged himself; Manchu forces entered through the Great Wall and founded the Qing, who ruled China until 1912."},
{d:"1648-01-30",t:"Peace of Münster",c:"pol",i:1,r:"Europe",s:"Spain finally recognised Dutch independence after eighty years of war, confirming the Republic as a sovereign state and a first-rank commercial power."},
{d:"1648-10-24",t:"Peace of Westphalia",c:"pol",i:1,r:"Europe",s:"Ended the Thirty Years' War and settled that states, not confessions, were the units of European politics — the origin of the modern idea of sovereignty."},
{d:"1649-01-30",t:"Execution of Charles I",c:"pol",i:1,r:"Europe",s:"A reigning king was tried and beheaded by his own subjects, a rupture that made every later European monarch calculate differently."},
{d:"1651-10-09",t:"English Navigation Acts",c:"econ",i:2,r:"Europe",s:"Restricted colonial trade to English ships, aimed squarely at Dutch carriers and triggering the first of three Anglo-Dutch wars."},
{d:"1652-04-06",t:"Cape Colony founded",c:"pol",i:2,r:"Africa",s:"Jan van Riebeeck's VOC supply station at the Cape grew into a settler colony — the origin of the Afrikaner population and of South Africa's racial order."},
{d:"1652-07-10",t:"First Anglo-Dutch War",c:"war",i:2,r:"Europe",s:"Two Protestant republics fought over trade and shipping rights, the first of the commercial wars that transferred maritime primacy from Amsterdam to London."},
{d:"1654-01-26",t:"Dutch lose Brazil",c:"war",i:2,r:"Americas",s:"Portuguese settlers expelled the WIC from Recife, ending Dutch America's most valuable possession and pushing Dutch sugar capital toward the Caribbean."},
{d:"1656-05-12",t:"Dutch take Colombo",c:"war",i:3,r:"Asia",s:"The VOC displaced Portugal in Ceylon, capturing the cinnamon trade it monopolised for the next 140 years."},
{d:"1660-05-29",t:"Restoration of Charles II",c:"pol",i:3,r:"Europe",s:"The monarchy returned after eleven years of republic, but on terms that left Parliament's financial power intact."},
{d:"1661-03-09",t:"Louis XIV takes personal rule",c:"pol",i:2,r:"Europe",s:"On Mazarin's death the young king governed without a chief minister for 54 years, making France the model of centralised absolutism."},
{d:"1664-09-08",t:"England takes New Amsterdam",c:"war",i:2,r:"Americas",s:"An English squadron seized the town without a shot and renamed it New York, closing the Dutch presence on the North American mainland."},
{d:"1665-03-04",t:"Second Anglo-Dutch War",c:"war",i:2,r:"Europe",s:"Fought over trade in West Africa and North America, it ended with a Dutch raid up the Thames and a settlement favourable to the Republic."},
{d:"1665",t:"Great Plague of London",c:"shock",i:3,r:"Europe",s:"Bubonic plague killed roughly a quarter of London's population in a year, the last major English outbreak."},
{d:"1666-09-02",t:"Great Fire of London",c:"shock",i:3,r:"Europe",s:"Four days of fire destroyed most of the medieval city; the rebuilding produced modern fire insurance and new building codes."},
{d:"1667-06-19",t:"Raid on the Medway",c:"war",i:3,r:"Europe",s:"De Ruyter burned the English fleet at anchor and towed away its flagship — the worst defeat in Royal Navy history."},
{d:"1667-07-31",t:"Treaty of Breda",c:"pol",i:2,r:"Global",s:"The Dutch kept Suriname's sugar and gave up New Netherland; contemporaries thought they had the better of it, and by the arithmetic of 1667 they did."},
{d:"1670-05-02",t:"Hudson's Bay Company",c:"econ",i:3,r:"Americas",s:"A charter over the entire Hudson Bay watershed created a fur monopoly that governed much of Canada for two centuries."},
{d:"1672-04-06",t:"The Dutch Disaster Year",c:"war",i:2,r:"Europe",s:"France, England and two German bishoprics attacked at once; the Republic survived by flooding its own land, but the Rampjaar ended its great-power ambitions and killed Johan de Witt."},
{d:"1683-09-12",t:"Ottoman defeat at Vienna",c:"war",i:2,r:"Europe",s:"A Polish-led relief army broke the siege, beginning the long Habsburg reconquest of Hungary and the Ottoman retreat from central Europe."},
{d:"1685-10-18",t:"Revocation of the Edict of Nantes",c:"pol",i:2,r:"Europe",s:"Louis XIV outlawed Protestantism; some 200,000 Huguenots fled, taking skills and capital to the Dutch Republic, England and Prussia."},
{d:"1688-11-05",t:"Glorious Revolution",c:"pol",i:1,r:"Europe",s:"William of Orange landed in England with a Dutch army and took the throne, binding England to the Dutch war against France and subordinating the crown to Parliament."},
{d:"1689-12-16",t:"English Bill of Rights",c:"pol",i:1,r:"Europe",s:"Barred the crown from taxing or keeping an army without Parliament, the settlement that made English public credit — and later British power — possible."},
{d:"1694-07-27",t:"Bank of England founded",c:"econ",i:1,r:"Europe",s:"Created to lend the government money for the French war, it turned national debt into a permanent, tradable instrument and gave Britain cheaper credit than its rivals for two centuries."},
{d:"1699-01-26",t:"Treaty of Karlowitz",c:"pol",i:3,r:"Europe",s:"The Ottomans ceded Hungary and Transylvania, the first treaty in which they negotiated as a defeated power."},

// ── 1700s ──────────────────────────────────────────────────────────────────────
{d:"1701-05-15",t:"War of the Spanish Succession",c:"war",i:2,r:"Europe",s:"Thirteen years of war to stop France and Spain uniting under one crown, fought from Flanders to the Caribbean and settled by the first true balance-of-power treaty."},
{d:"1703-05-27",t:"St Petersburg founded",c:"pol",i:3,r:"Europe",s:"Peter the Great built a capital on captured marshland to face Europe, the physical statement of Russian westernisation."},
{d:"1707-05-01",t:"Acts of Union",c:"pol",i:2,r:"Europe",s:"England and Scotland merged into Great Britain, creating a single market and the state that would build the largest empire in history."},
{d:"1709-07-08",t:"Battle of Poltava",c:"war",i:2,r:"Europe",s:"Peter the Great destroyed the Swedish army, ending Sweden's empire and making Russia the dominant power in the north."},
{d:"1713-04-11",t:"Treaty of Utrecht",c:"pol",i:1,r:"Europe",s:"Settled the Spanish succession by explicit balance of power and handed Britain Gibraltar and the asiento — the contract to supply enslaved Africans to Spanish America."},
{d:"1715-09-01",t:"Death of Louis XIV",c:"pol",i:3,r:"Europe",s:"Seventy-two years on the throne left France dominant in culture and exhausted in finance, a debt problem that ran to 1789."},
{d:"1720-06",t:"South Sea and Mississippi bubbles",c:"econ",i:1,r:"Europe",s:"Two schemes to convert national debt into company shares collapsed within months of each other in London and Paris, ruining thousands and delaying joint-stock finance in Britain for a century."},
{d:"1721-09-10",t:"Treaty of Nystad",c:"pol",i:3,r:"Europe",s:"Ended the Great Northern War; Russia gained the Baltic coast and was proclaimed an empire."},
{d:"1739-10-23",t:"War of Jenkins' Ear",c:"war",i:3,r:"Americas",s:"A trade war between Britain and Spain in the Caribbean that widened into the general European war of the 1740s."},
{d:"1740-12-16",t:"War of the Austrian Succession",c:"war",i:2,r:"Europe",s:"Frederick the Great's seizure of Silesia announced Prussia as a great power and set up the Anglo-French global war that followed."},
{d:"1755-11-01",t:"Lisbon earthquake",c:"shock",i:2,r:"Europe",s:"A quake, fire and tsunami destroyed one of Europe's richest capitals on All Saints' Day, shaking Enlightenment confidence and prompting the first state-led disaster reconstruction."},
{d:"1756-05-17",t:"Seven Years' War",c:"war",i:1,r:"Global",s:"Fought in Europe, North America, the Caribbean, West Africa and India, it is often called the first world war — and it left Britain dominant and both sides deeply in debt."},
{d:"1757-06-23",t:"Battle of Plassey",c:"war",i:1,r:"Asia",s:"Clive's victory, secured mostly by bribing the Nawab's commander, gave the East India Company control of Bengal's revenues and began British rule in India."},
{d:"1763-02-10",t:"Treaty of Paris 1763",c:"pol",i:1,r:"Global",s:"France surrendered Canada and its claims in India; Britain emerged supreme and immediately began taxing its American colonies to pay for the war."},
{d:"1765-03-22",t:"Stamp Act",c:"pol",i:3,r:"Americas",s:"The first direct British tax on the colonies produced the slogan about taxation and representation, and was repealed within a year."},
{d:"1769",t:"Watt's steam engine patent",c:"econ",i:2,r:"Europe",s:"The separate condenser cut fuel use by three-quarters and made steam power economic away from coalfields — the enabling technology of industrialisation."},
{d:"1769",t:"Great Bengal famine",c:"shock",i:2,r:"Asia",s:"Perhaps ten million died, roughly a third of the population, under Company revenue policies that kept collecting through the failure of the rains."},
{d:"1772-08-05",t:"First Partition of Poland",c:"pol",i:2,r:"Europe",s:"Russia, Prussia and Austria took a third of the Commonwealth between them, the first of three partitions that erased Poland from the map for 123 years."},
{d:"1773-12-16",t:"Boston Tea Party",c:"pol",i:3,r:"Americas",s:"Colonists destroyed East India Company tea over a tax designed to rescue the Company; Britain's punitive response united the colonies."},
{d:"1775-04-19",t:"American Revolutionary War",c:"war",i:1,r:"Americas",s:"Fighting at Lexington began a war that France, Spain and the Dutch Republic joined, turning a colonial revolt into a global contest and bankrupting the French crown."},
{d:"1776-03-09",t:"The Wealth of Nations",c:"econ",i:2,r:"Europe",s:"Adam Smith argued that specialisation and open trade, not hoarded bullion, create national wealth — the founding text of economics and the case against mercantilism."},
{d:"1776-07-04",t:"US Declaration of Independence",c:"pol",i:1,r:"Americas",s:"Thirteen colonies claimed sovereignty on the argument that governments derive their authority from the consent of the governed."},
{d:"1781-10-19",t:"Surrender at Yorktown",c:"war",i:2,r:"Americas",s:"Washington and a French fleet trapped Cornwallis, effectively ending British efforts to hold the colonies."},
{d:"1783-09-03",t:"Treaty of Paris 1783",c:"pol",i:2,r:"Americas",s:"Britain recognised American independence and ceded land to the Mississippi, while the Dutch — on the losing side of a parallel war — lost trading posts and prestige."},
{d:"1787-09-17",t:"US Constitution signed",c:"pol",i:1,r:"Americas",s:"Created a federal republic with separated powers and a written supreme law, the template copied by constitution-writers ever since — and it protected slavery."},
{d:"1789-07-14",t:"French Revolution begins",c:"pol",i:1,r:"Europe",s:"The storming of the Bastille turned a fiscal crisis into a revolution that abolished monarchy, nobility and the old European order."},
{d:"1789-08-26",t:"Rights of Man declared",c:"pol",i:2,r:"Europe",s:"Proclaimed liberty, property and equality before the law as universal, a text that armed both liberals and the colonised for the next two centuries."},
{d:"1791-08-22",t:"Haitian Revolution begins",c:"pol",i:1,r:"Americas",s:"Enslaved people in France's richest colony rose and, after thirteen years, founded the first state created by a successful slave revolt."},
{d:"1793-01-21",t:"Execution of Louis XVI",c:"pol",i:2,r:"Europe",s:"The king's death by guillotine brought Britain and Spain into the war and hardened counter-revolution across Europe."},
{d:"1793-09-05",t:"Reign of Terror",c:"pol",i:2,r:"Europe",s:"Some 17,000 were executed and many more died in prison before Robespierre himself fell, the episode that made 'revolution' frightening as well as inspiring."},
{d:"1795-01-19",t:"Batavian Republic",c:"pol",i:2,r:"Europe",s:"French troops and Dutch revolutionaries ended the old Republic; Britain seized the Cape and Ceylon from the new French client state, and the Dutch never got them back."},
{d:"1795-10-24",t:"Third Partition of Poland",c:"pol",i:2,r:"Europe",s:"The Commonwealth was extinguished entirely, an act of state erasure that shaped European nationalism for a century."},
{d:"1798-07-01",t:"Napoleon invades Egypt",c:"war",i:2,r:"MidEast",s:"An attempt to cut Britain's route to India ended in naval disaster, but it opened Egypt to European intervention and began modern Egyptology."},
{d:"1798-06",t:"Malthus on population",c:"econ",i:3,r:"Europe",s:"Argued that population outruns food supply — wrong about the future, but it framed a century of debate on poverty, and gave economics its 'dismal science' label."},
{d:"1799-11-09",t:"Napoleon seizes power",c:"pol",i:1,r:"Europe",s:"The coup of 18 Brumaire ended the Revolution's republican phase and began fifteen years in which one man reorganised Europe."},
{d:"1799-12-31",t:"VOC dissolved",c:"econ",i:1,r:"Global",s:"Bankrupted by corruption, war and competition, the world's first great multinational was wound up and its debts and territories taken over by the Dutch state — which is how a company's possessions became the Dutch East Indies."},

// ── 1800s ──────────────────────────────────────────────────────────────────────
{d:"1803-04-30",t:"Louisiana Purchase",c:"econ",i:1,r:"Americas",s:"Napoleon sold 2.1 million square kilometres for $15 million after Haiti's revolt destroyed his American plans, doubling the United States at about four cents a hectare."},
{d:"1804-01-01",t:"Haitian independence",c:"pol",i:1,r:"Americas",s:"The first free state in Latin America and the only one founded by former slaves; France's 1825 indemnity demand crippled it financially for over a century."},
{d:"1804-05-18",t:"Napoleon crowned Emperor",c:"pol",i:2,r:"Europe",s:"The Revolution ended in a hereditary empire, but the Napoleonic Code it exported reshaped law across Europe and Latin America."},
{d:"1805-10-21",t:"Battle of Trafalgar",c:"war",i:2,r:"Europe",s:"Nelson's destruction of the Franco-Spanish fleet ended any prospect of invading Britain and secured a century of Royal Navy supremacy."},
{d:"1805-12-02",t:"Battle of Austerlitz",c:"war",i:2,r:"Europe",s:"Napoleon's most complete victory broke the Third Coalition and left him master of continental Europe."},
{d:"1806-06-05",t:"Kingdom of Holland",c:"pol",i:3,r:"Europe",s:"Napoleon installed his brother Louis as king of the Dutch; when Louis proved too sympathetic to Dutch interests, France annexed the country outright in 1810."},
{d:"1806-08-06",t:"End of the Holy Roman Empire",c:"pol",i:2,r:"Europe",s:"Francis II abdicated the thousand-year title under Napoleonic pressure, clearing the ground on which German nationalism was later built."},
{d:"1806-11-21",t:"Continental System",c:"econ",i:2,r:"Europe",s:"Napoleon's attempt to close Europe to British trade smuggled itself to death, hurt his allies more than his enemy, and led him into Russia."},
{d:"1807-03-25",t:"Britain abolishes the slave trade",c:"pol",i:1,r:"Global",s:"The Slave Trade Act ended British participation in the Atlantic traffic and set the Royal Navy to suppressing it — a moral turn that also served British commercial interests."},
{d:"1808-05-02",t:"Peninsular War",c:"war",i:2,r:"Europe",s:"Spanish and Portuguese resistance to French occupation bled Napoleon's armies for six years and broke Spanish authority over its American colonies."},
{d:"1810-05-25",t:"May Revolution in Buenos Aires",c:"pol",i:2,r:"Americas",s:"With Spain under French occupation, the viceroy was deposed and a local junta took power — the opening of South America's independence wars."},
{d:"1810-09-16",t:"Mexican War of Independence",c:"war",i:2,r:"Americas",s:"Father Hidalgo's call to arms began eleven years of war that ended Spanish rule over the richest colony in the Americas."},
{d:"1812-06-18",t:"War of 1812",c:"war",i:3,r:"Americas",s:"A stalemate over shipping rights and westward expansion that confirmed the border with Canada and ended Native resistance east of the Mississippi."},
{d:"1812-06-24",t:"Napoleon invades Russia",c:"war",i:1,r:"Europe",s:"Around 600,000 men crossed the Niemen and perhaps a tenth came back; the destruction of the Grande Armée began the collapse of Napoleonic Europe."},
{d:"1815-03-16",t:"United Kingdom of the Netherlands",c:"pol",i:2,r:"Europe",s:"The Congress powers joined the Dutch and Belgian provinces into a buffer against France; the union split fifteen years later, but the Dutch got their colonies back."},
{d:"1815-04-10",t:"Tambora erupts",c:"shock",i:2,r:"Asia",s:"The largest eruption in recorded history cooled the planet, producing the 1816 'year without a summer', harvest failure and food riots across Europe and North America."},
{d:"1815-06-18",t:"Battle of Waterloo",c:"war",i:1,r:"Europe",s:"Ended twenty-three years of war begun by the Revolution, and opened a century in which no general European war was fought."},
{d:"1815-06-09",t:"Congress of Vienna",c:"pol",i:1,r:"Europe",s:"The victors redrew the map around a balance of power and monarchical legitimacy, a settlement that held with modifications until 1914."},
{d:"1819-08-07",t:"Battle of Boyacá",c:"war",i:2,r:"Americas",s:"Bolívar's victory secured New Granada and led to the creation of Gran Colombia."},
{d:"1821-03-25",t:"Greek War of Independence",c:"war",i:2,r:"Europe",s:"The first successful nationalist revolt against Ottoman rule, won with British, French and Russian intervention and celebrated across liberal Europe."},
{d:"1821-09-27",t:"Mexican independence",c:"pol",i:2,r:"Americas",s:"Spanish rule ended after eleven years of war, leaving a vast, indebted and politically fractured state."},
{d:"1822-09-07",t:"Brazilian independence",c:"pol",i:2,r:"Americas",s:"The Portuguese heir declared independence and crowned himself emperor — the only Latin American state to become a monarchy, and the last to abolish slavery."},
{d:"1823-12-02",t:"Monroe Doctrine",c:"pol",i:2,r:"Americas",s:"Washington declared the Americas closed to further European colonisation, a claim it could not yet enforce and later used to justify its own interventions."},
{d:"1824-03-17",t:"Anglo-Dutch Treaty",c:"pol",i:2,r:"Asia",s:"Britain and the Netherlands divided Southeast Asia along the Strait of Malacca — the Dutch kept the Indies, the British kept Malaya and Singapore, and the line still runs between Indonesia and Malaysia."},
{d:"1824-12-09",t:"Battle of Ayacucho",c:"war",i:1,r:"Americas",s:"The last major battle of the Spanish American wars ended three centuries of Spanish rule on the mainland."},
{d:"1825-09-27",t:"First public steam railway",c:"econ",i:2,r:"Europe",s:"The Stockton and Darlington line proved steam haulage on rails, beginning the transport revolution that reorganised industry, cities and warfare."},
{d:"1830-07-27",t:"July Revolution",c:"pol",i:2,r:"Europe",s:"Three days of Paris fighting replaced the restored Bourbons with a constitutional monarchy, and set off imitations across Europe."},
{d:"1830-08-25",t:"Belgian Revolution",c:"pol",i:2,r:"Europe",s:"Belgium broke from the Netherlands and was guaranteed neutrality by the powers — the treaty Germany violated in 1914."},
{d:"1830",t:"Cultivation System in Java",c:"econ",i:2,r:"Asia",s:"Dutch authorities required Javanese villages to devote land and labour to export crops; the profits at times covered a third of the Netherlands' budget, and the system caused repeated local famine."},
{d:"1833-08-28",t:"Slavery abolished in the British Empire",c:"pol",i:1,r:"Global",s:"Freed some 800,000 people, and paid £20 million in compensation — to the slave owners, a debt Britain finished repaying in 2015."},
{d:"1834-01-01",t:"German Zollverein",c:"econ",i:2,r:"Europe",s:"A customs union among German states created a single market under Prussian leadership, doing much of the work of unification before politics caught up."},
{d:"1839-09-04",t:"First Opium War",c:"war",i:1,r:"Asia",s:"Britain went to war to force China to accept opium imports; defeat began the 'century of humiliation' that still frames Chinese foreign policy."},
{d:"1842-08-29",t:"Treaty of Nanking",c:"pol",i:1,r:"Asia",s:"China ceded Hong Kong, opened five treaty ports and paid an indemnity — the first of the unequal treaties."},
{d:"1845-09",t:"Great Irish Famine",c:"shock",i:1,r:"Europe",s:"Potato blight and a government committed to free-market non-intervention killed about a million people and drove a million more abroad; Ireland's population has never recovered."},
{d:"1846-06-25",t:"Repeal of the Corn Laws",c:"econ",i:1,r:"Europe",s:"Britain abandoned agricultural protection for free trade, splitting the Conservative party and setting the terms of world commerce for seventy years."},
{d:"1848-01-24",t:"California Gold Rush",c:"econ",i:2,r:"Americas",s:"300,000 migrants arrived within a few years, accelerating US expansion to the Pacific and adding enough gold to loosen world money."},
{d:"1848-02-21",t:"The Communist Manifesto",c:"pol",i:2,r:"Europe",s:"Published weeks before the revolutions of 1848 and little noticed then, it became the founding text of the movement that governed a third of humanity by 1950."},
{d:"1848-02-22",t:"Revolutions of 1848",c:"pol",i:1,r:"Europe",s:"Uprisings in more than fifty countries demanded constitutions, national self-determination and the vote; nearly all were crushed within a year, and nearly all their demands were met within seventy."},
{d:"1850-12",t:"Taiping Rebellion",c:"war",i:1,r:"Asia",s:"A millenarian revolt against the Qing became the deadliest civil war in history, killing perhaps 20–30 million and gutting the dynasty's authority."},
{d:"1853-07-08",t:"Perry opens Japan",c:"pol",i:1,r:"Asia",s:"American steam warships in Edo Bay forced Japan to end two centuries of seclusion, discrediting the shogunate and setting off the fastest modernisation in history."},
{d:"1853-10-16",t:"Crimean War",c:"war",i:2,r:"Europe",s:"The first war between great powers since 1815 exposed Russian backwardness, killed the Concert of Europe and introduced the telegraph, railways and war correspondents to conflict."},
{d:"1857-05-10",t:"Indian Rebellion",c:"war",i:1,r:"Asia",s:"A mutiny of Company sepoys became a widespread revolt; its suppression ended the East India Company and put India under direct Crown rule."},
{d:"1857-08-24",t:"Panic of 1857",c:"econ",i:3,r:"Global",s:"A bank failure in Ohio spread by telegraph to Europe within weeks — arguably the first worldwide financial crisis."},
{d:"1860",t:"Max Havelaar published",c:"pol",i:3,r:"Asia",s:"A novel exposing abuses under the Cultivation System shamed Dutch opinion and eventually produced the reforms of the 'Ethical Policy'."},
{d:"1861-03-03",t:"Russian serfs emancipated",c:"pol",i:1,r:"Europe",s:"Freed 23 million people, but the redemption payments tied them to the land and stored up the grievances of 1905 and 1917."},
{d:"1861-03-17",t:"Kingdom of Italy proclaimed",c:"pol",i:2,r:"Europe",s:"Unification under Piedmont created a new great power and left the Papal States as the unfinished business of 1870."},
{d:"1861-04-12",t:"American Civil War",c:"war",i:1,r:"Americas",s:"Four years of industrial war over slavery and secession killed some 700,000 and settled that the United States was one nation."},
{d:"1863-01-01",t:"Emancipation Proclamation",c:"pol",i:1,r:"Americas",s:"Declared the enslaved in rebel states free, turned the war into a war against slavery, and made European recognition of the Confederacy impossible."},
{d:"1863-07-01",t:"Dutch abolish slavery",c:"pol",i:2,r:"Americas",s:"Some 45,000 people in Suriname and the Antilles were freed, decades after Britain and with a further ten years of compulsory labour attached."},
{d:"1865-04-09",t:"US Civil War ends",c:"war",i:2,r:"Americas",s:"Lee's surrender at Appomattox was followed within days by Lincoln's assassination, leaving Reconstruction to a hostile successor."},
{d:"1866-07-03",t:"Battle of Königgrätz",c:"war",i:2,r:"Europe",s:"Prussia's needle guns and railways defeated Austria in seven weeks, deciding that Germany would be unified without Vienna."},
{d:"1867-02-08",t:"Austro-Hungarian Compromise",c:"pol",i:2,r:"Europe",s:"Turned the Habsburg empire into a dual monarchy, buying fifty years of stability by privileging two nationalities over a dozen others."},
{d:"1867-03-30",t:"Alaska Purchase",c:"econ",i:3,r:"Americas",s:"The US bought 1.5 million square kilometres from Russia for $7.2 million, mocked at the time as Seward's Folly."},
{d:"1867-07-01",t:"Canadian Confederation",c:"pol",i:2,r:"Americas",s:"Four provinces federated into a self-governing dominion, the model for peaceful evolution from colony to nation within the empire."},
{d:"1868-01-03",t:"Meiji Restoration",c:"pol",i:1,r:"Asia",s:"Samurai reformers overthrew the shogunate in the emperor's name and rebuilt Japan as an industrial nation-state — within forty years it defeated Russia."},
{d:"1869-05-10",t:"US transcontinental railroad",c:"econ",i:2,r:"Americas",s:"Cut the coast-to-coast journey from months to a week, integrating a continental market and opening the plains to settlement and dispossession."},
{d:"1869-11-17",t:"Suez Canal opens",c:"econ",i:1,r:"MidEast",s:"Cut the London–Bombay voyage by 7,000 kilometres, made steamships dominant, and turned Egypt into a strategic prize Britain occupied thirteen years later."},
{d:"1870-07-19",t:"Franco-Prussian War",c:"war",i:2,r:"Europe",s:"Prussia's rapid victory, the capture of Napoleon III and the annexation of Alsace-Lorraine created a French grievance that lasted until 1918."},
{d:"1871-01-18",t:"German Empire proclaimed",c:"pol",i:1,r:"Europe",s:"Declared in the Hall of Mirrors at Versailles, the new Reich immediately became continental Europe's strongest economy and army."},
{d:"1871-03-18",t:"Paris Commune",c:"pol",i:2,r:"Europe",s:"Two months of radical self-government ended with perhaps 10,000 killed in a week; it became the founding martyrdom of the socialist left."},
{d:"1873-03-26",t:"Aceh War begins",c:"war",i:2,r:"Asia",s:"The Netherlands' longest and bloodiest colonial war ran for three decades, killed over 100,000 and completed Dutch control of the archipelago."},
{d:"1873-05-09",t:"Panic of 1873",c:"econ",i:1,r:"Global",s:"A Vienna crash spread worldwide and began the Long Depression — two decades of falling prices, the retreat from free trade, and the tariff politics that followed."},
{d:"1876",t:"Great Famine in India",c:"shock",i:2,r:"Asia",s:"Drought and a colonial administration that kept exporting grain killed between five and ten million people."},
{d:"1878-06-13",t:"Congress of Berlin",c:"pol",i:2,r:"Europe",s:"Bismarck redrew the Balkans to contain Russia, creating the half-finished states whose grievances detonated in 1914."},
{d:"1882-09-13",t:"Britain occupies Egypt",c:"pol",i:2,r:"Africa",s:"Intervention to protect bondholders and the Suez Canal became a seventy-year occupation, and the opening move of the scramble for Africa."},
{d:"1884-11-15",t:"Berlin Conference",c:"pol",i:1,r:"Africa",s:"European powers agreed the rules for partitioning Africa without a single African present; within thirty years almost the entire continent was under European rule."},
{d:"1885-12-28",t:"Indian National Congress founded",c:"pol",i:2,r:"Asia",s:"Began as a loyal debating society for the educated elite and became the organisation that won independence and governed India for most of its first fifty years."},
{d:"1886-06",t:"Witwatersrand gold discovered",c:"econ",i:2,r:"Africa",s:"The world's largest goldfield turned the Transvaal into a magnet for capital and migrants, and set Britain and the Boer republics on the road to war."},
{d:"1888-05-13",t:"Brazil abolishes slavery",c:"pol",i:2,r:"Americas",s:"The last country in the Americas to do so freed 700,000 people; the monarchy that signed the law was overthrown eighteen months later."},
{d:"1890-03-18",t:"Bismarck dismissed",c:"pol",i:2,r:"Europe",s:"Wilhelm II dropped the pilot and let the Russian treaty lapse, freeing Russia to ally with France and beginning Germany's encirclement."},
{d:"1893-05-05",t:"Panic of 1893",c:"econ",i:3,r:"Americas",s:"Railroad overbuilding and gold drain produced the worst US depression before the 1930s, with unemployment above 15% for years."},
{d:"1894-08-01",t:"First Sino-Japanese War",c:"war",i:1,r:"Asia",s:"Japan's swift defeat of China reversed two thousand years of regional order, took Taiwan and Korea from Chinese influence and announced a new imperial power."},
{d:"1896-03-01",t:"Battle of Adwa",c:"war",i:2,r:"Africa",s:"Ethiopia destroyed an invading Italian army, the only decisive African victory over a European power in the scramble — and the reason Ethiopia stayed independent."},
{d:"1898-04-25",t:"Spanish–American War",c:"war",i:1,r:"Americas",s:"Ten weeks of fighting ended Spain's empire and gave the United States Puerto Rico, Guam and the Philippines — its first overseas colonies."},
{d:"1899-02-04",t:"Philippine–American War",c:"war",i:2,r:"Asia",s:"Filipinos who had fought Spain then fought the United States; the war killed perhaps 200,000 civilians and settled that America would keep the islands."},
{d:"1899-10-11",t:"Second Boer War begins",c:"war",i:2,r:"Africa",s:"Britain committed 450,000 troops against two small republics, and resorted to farm burning and concentration camps that damaged its standing abroad."},

// ── late addition to the modern range ──────────────────────────────────────────
{d:"1901",t:"Dutch Ethical Policy",c:"pol",i:3,r:"Asia",s:"The Netherlands accepted a 'debt of honour' to the Indies and promised education, irrigation and welfare — reforms that were underfunded, but which trained the generation that led the independence movement."},
{d:"1975-11-25",t:"Suriname independence",c:"pol",i:2,r:"Americas",s:"The last substantial Dutch colony became independent; a third of the population emigrated to the Netherlands within a few years, and the Caribbean islands chose to stay."},

// ── Second pass on the early centuries: gaps, and less Europe ─────────────────
{d:"1624",t:"Nzinga becomes queen of Ndongo",c:"pol",i:3,r:"Africa",s:"She fought Portuguese slave-raiding for four decades by diplomacy and war, and became the enduring symbol of African resistance to the Atlantic trade."},
{d:"1642-11-24",t:"Tasman reaches Van Diemen's Land",c:"pol",i:3,r:"Oceania",s:"A VOC expedition charted Tasmania and New Zealand, proving Australia was not part of a great southern continent — and finding nothing the Company thought worth trading for."},
{d:"1655-05-10",t:"England takes Jamaica",c:"war",i:3,r:"Americas",s:"A failed attack on Hispaniola was salvaged by seizing Jamaica, which became Britain's most valuable sugar and slave colony."},
{d:"1659-11-07",t:"Treaty of the Pyrenees",c:"pol",i:3,r:"Europe",s:"Ended the long Franco-Spanish war and marked the passing of European primacy from Madrid to Paris."},
{d:"1662-02-01",t:"Dutch expelled from Taiwan",c:"war",i:3,r:"Asia",s:"Koxinga's Ming loyalists took Fort Zeelandia after a nine-month siege, ending 38 years of VOC rule on the island."},
{d:"1674-02-19",t:"Treaty of Westminster",c:"pol",i:3,r:"Europe",s:"Ended the Third Anglo-Dutch War and confirmed English possession of New York; the Republic survived, but as a junior naval power."},
{d:"1675-06-20",t:"King Philip's War",c:"war",i:3,r:"Americas",s:"The bloodiest conflict per capita in American history broke Native power in southern New England."},
{d:"1678-08-10",t:"Treaty of Nijmegen",c:"pol",i:3,r:"Europe",s:"Ended Louis XIV's Dutch War with France dominant on land, and left William of Orange determined to build a coalition against it."},
{d:"1680-08-10",t:"Pueblo Revolt",c:"war",i:3,r:"Americas",s:"Coordinated risings drove the Spanish out of New Mexico for twelve years, the most successful Native rebellion in North America."},
{d:"1685-03",t:"Code Noir",c:"pol",i:3,r:"Americas",s:"France codified the treatment of enslaved people in its colonies, giving slavery a legal architecture that lasted until 1848."},
{d:"1687",t:"Mughal Empire at its height",c:"pol",i:3,r:"Asia",s:"Aurangzeb's conquest of Golconda brought almost all India under one ruler; the wars that achieved it also exhausted the treasury."},
{d:"1690-07-01",t:"Battle of the Boyne",c:"war",i:3,r:"Europe",s:"William III's victory over the deposed James II secured the Glorious Revolution and Protestant ascendancy in Ireland."},
{d:"1698-12-13",t:"Oman takes Mombasa",c:"war",i:3,r:"Africa",s:"The fall of Fort Jesus ended Portuguese power on the Swahili coast and built the Omani commercial empire that later ran Zanzibar."},
{d:"1707-03-03",t:"Death of Aurangzeb",c:"pol",i:2,r:"Asia",s:"The Mughal Empire began to fragment almost immediately, opening the space that regional rulers, and then the East India Company, moved into."},
{d:"1722-10-23",t:"Fall of Isfahan",c:"pol",i:2,r:"MidEast",s:"Afghan invaders ended the Safavid dynasty after two centuries, beginning a long period of instability in Iran."},
{d:"1733",t:"Flying shuttle",c:"econ",i:3,r:"Europe",s:"Kay's device doubled weaving speed and created the yarn shortage that spinning machinery was invented to solve — the first link in the industrial chain."},
{d:"1733-10-10",t:"War of the Polish Succession",c:"war",i:3,r:"Europe",s:"A dynastic war fought mainly in Italy and the Rhineland that confirmed Russian influence over Poland."},
{d:"1739-02-24",t:"Nader Shah sacks Delhi",c:"war",i:2,r:"Asia",s:"The Persian invader carried off the Peacock Throne and the Koh-i-Noor, and left the Mughal Empire a shell."},
{d:"1745-08-19",t:"Jacobite rising",c:"war",i:3,r:"Europe",s:"The last serious attempt to restore the Stuarts ended at Culloden, followed by the destruction of the Highland clan system."},
{d:"1748-10-18",t:"Treaty of Aix-la-Chapelle",c:"pol",i:3,r:"Europe",s:"Restored most conquests and settled nothing; both sides began preparing for the war that came eight years later."},
{d:"1750-01-13",t:"Treaty of Madrid",c:"pol",i:3,r:"Americas",s:"Spain and Portugal replaced the Tordesillas line with borders based on actual settlement, roughly the shape of Brazil today."},
{d:"1754-05-28",t:"French and Indian War",c:"war",i:2,r:"Americas",s:"A skirmish involving a young George Washington in the Ohio valley grew into the North American theatre of the Seven Years' War."},
{d:"1762-07-09",t:"Catherine the Great takes power",c:"pol",i:2,r:"Europe",s:"A coup against her husband began 34 years in which Russia took Crimea, partitioned Poland and became a European arbiter."},
{d:"1764-10-22",t:"Battle of Buxar",c:"war",i:2,r:"Asia",s:"The East India Company's victory won it the right to collect Bengal's taxes — the moment a trading company became a territorial government."},
{d:"1770-04-29",t:"Cook reaches Botany Bay",c:"pol",i:2,r:"Oceania",s:"Britain claimed the east coast of Australia as terra nullius, a legal fiction overturned only in 1992."},
{d:"1774-07-21",t:"Treaty of Küçük Kaynarca",c:"pol",i:2,r:"MidEast",s:"Russia gained access to the Black Sea and a claim to protect Ottoman Christians — the opening of the Eastern Question."},
{d:"1780-12-20",t:"Fourth Anglo-Dutch War",c:"war",i:2,r:"Europe",s:"Britain attacked the Republic for trading with the American rebels; the Dutch merchant fleet was swept from the seas and never recovered its share of world trade."},
{d:"1788-01-26",t:"First Fleet reaches Sydney",c:"pol",i:2,r:"Oceania",s:"A penal colony of 1,400 began the British settlement of Australia and the dispossession of its Aboriginal peoples."},
{d:"1793-02-01",t:"French Revolutionary Wars",c:"war",i:2,r:"Europe",s:"France declared war on Britain and the Dutch Republic, beginning 22 years of near-continuous European war and the first mass conscript armies."},
{d:"1795-09-16",t:"Britain takes the Cape",c:"war",i:3,r:"Africa",s:"With the Netherlands under French control, Britain seized the Cape Colony — returned briefly, retaken in 1806, and kept."},
{d:"1796-08",t:"Britain takes Dutch Ceylon",c:"war",i:3,r:"Asia",s:"The VOC's cinnamon island passed to Britain, another of the losses that followed from the Netherlands becoming a French satellite."},
{d:"1804",t:"Sokoto Caliphate founded",c:"pol",i:3,r:"Africa",s:"Usman dan Fodio's jihad built the largest state in nineteenth-century Africa, whose emirates the British later governed through indirect rule."},
{d:"1818",t:"Rise of the Zulu kingdom",c:"pol",i:3,r:"Africa",s:"Shaka's military reorganisation created a regional power and set off the Mfecane, a wave of displacement across southern Africa."},
{d:"1830-07-05",t:"France invades Algeria",c:"war",i:2,r:"Africa",s:"Begun as a distraction from domestic crisis, the conquest took decades, killed hundreds of thousands and created a settler colony France treated as part of itself."},
{d:"1836",t:"The Great Trek",c:"pol",i:3,r:"Africa",s:"Boer families left the Cape to escape British rule and the abolition of slavery, founding the inland republics that Britain fought in 1899."},
{d:"1856-10-08",t:"Second Opium War",c:"war",i:2,r:"Asia",s:"Britain and France forced further concessions from China, legalised the opium trade and opened the interior to foreign missions and merchants."},
{d:"1860-10-18",t:"Burning of the Summer Palace",c:"war",i:3,r:"Asia",s:"British and French troops destroyed the Qing imperial gardens in reprisal, an act still cited in China as the emblem of foreign humiliation."},
{d:"1862-05-20",t:"Homestead Act",c:"econ",i:3,r:"Americas",s:"Offered 160 acres to any settler who farmed it for five years, accelerating westward migration and the removal of Native nations from the plains."},
{d:"1864-11-13",t:"Paraguayan War",c:"war",i:2,r:"Americas",s:"The deadliest inter-state war in Latin American history killed most of Paraguay's adult male population and left it permanently diminished."},
{d:"1875-11-25",t:"Britain buys the Suez shares",c:"econ",i:3,r:"Africa",s:"Disraeli borrowed from the Rothschilds overnight to buy Egypt's stake in the canal, tying Britain to Egyptian finances and, seven years later, to occupation."},
{d:"1879-01-11",t:"Anglo-Zulu War",c:"war",i:3,r:"Africa",s:"The destruction of a British column at Isandlwana was the worst defeat a colonial army inflicted on Britain; the kingdom was broken up within six months."},
{d:"1885-02-05",t:"Congo Free State",c:"pol",i:2,r:"Africa",s:"The Berlin Conference recognised Leopold II's personal ownership of a territory the size of western Europe; the rubber regime that followed killed millions."},
{d:"1891-05-31",t:"Trans-Siberian Railway begun",c:"econ",i:3,r:"Asia",s:"Nine thousand kilometres of track bound Russia's east to Europe, financed by French loans and aimed at Manchuria — one of the causes of war with Japan."},
{d:"1895-12-29",t:"Jameson Raid",c:"pol",i:3,r:"Africa",s:"A botched private attempt to overthrow the Transvaal government exposed British designs on the goldfields and made war far more likely."},
{d:"1898-09-18",t:"Fashoda Incident",c:"pol",i:3,r:"Africa",s:"A confrontation between French and British expeditions on the Nile brought the two empires close to war, then pushed them toward the Entente."},
{d:"1727-10-21",t:"Treaty of Kyakhta",c:"pol",i:3,r:"Asia",s:"Fixed the Russo-Chinese border and regulated the caravan trade, a settlement that held for over a century and kept the two empires at peace."},
{d:"1730-09-28",t:"Patrona Halil revolt",c:"pol",i:3,r:"MidEast",s:"A janissary uprising ended the Ottoman 'Tulip Period' of cautious westernisation and deposed the sultan, delaying reform for decades."},
{d:"1732-06-09",t:"Province of Georgia chartered",c:"pol",i:3,r:"Americas",s:"The last of the thirteen colonies was founded as a debtors' refuge and a military buffer against Spanish Florida."},
// __END__
];
if (typeof module !== "undefined") module.exports = EVENTS;
